	(519, "CVE-1999-1044", "1998-05-07T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Advanced File System Utility (advfs) in Digital UNIX 4.0 through 4.0d allows local users to gain privileges."),
	(520, "CVE-1999-1361", "1998-05-09T04:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 3.51 and 4.0 running WINS (Windows Internet Name Service) allows remote attackers to cause a denial of service (resource exhaustion) via a flood of malformed packets, which causes the server to slow down and fill the event logs with error messages."),
	(521, "CVE-1999-0816", "1998-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "The Motorola CableRouter allows any remote user to connect to and configure the router on port 1024."),
	(522, "CVE-1999-0919", "1998-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "A memory leak in a Motorola CableRouter allows remote attackers to conduct a denial of service via a large number of telnet connections."),
	(523, "CVE-1999-1204", "1998-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "Check Point Firewall-1 does not properly handle certain restricted keywords (e.g., Mail, auth, time) in user-defined objects, which could produce a rule with a default \"ANY\" address and result in access to more systems than intended by the administrator."),
	(524, "CVE-1999-1389", "1998-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "US Robotics/3Com Total Control Chassis with Frame Relay between 3.6.22 and 3.7.24 does not properly enforce access filters when the \"set host prompt\" setting is made for a port, which allows attackers to bypass restrictions by providing the hostname twice at the \"host: \" prompt."),
	(525, "CVE-1999-0055", "1998-05-14T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflows in Sun libnsl allow root access."),
	(526, "CVE-1999-1179", "1998-05-15T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in man.sh CGI script, included in May 1998 issue of SysAdmin Magazine, allows remote attackers to execute arbitrary commands."),
	(527, "CVE-1999-1096", "1998-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in kscreensaver in KDE klock allows local users to gain root privileges via a long HOME environmental variable."),
	(528, "CVE-1999-0303", "1998-05-21T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in BNU UUCP daemon (uucpd) through long hostnames."),
	(529, "CVE-1999-1039", "1998-05-27T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in (1) diskalign and (2) diskperf in IRIX 6.4 patches 2291 and 2848 allow a local user to create root-owned files leading to a root compromise."),
	(530, "CVE-1999-1492", "1998-05-27T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in (1) diskperf and (2) diskalign in IRIX 6.4 allows local attacker to create arbitrary root owned files, leading to root privileges."),
	(531, "CVE-1999-1490", "1998-05-28T04:00:00.000", "2025-04-03T01:03:51.193", "xosview 1.5.1 in Red Hat 5.1 allows local users to gain root access via a long HOME environmental variable."),
	(532, "CVE-1999-0278", "1998-06-01T04:00:00.000", "2025-04-03T01:03:51.193", "In IIS, remote attackers can obtain source code for ASP files by appending \"::$DATA\" to the URL."),
	(533, "CVE-1999-0329", "1998-06-01T04:00:00.000", "2025-04-03T01:03:51.193", "SGI mediad program allows local users to gain root access."),
	(534, "CVE-1999-0501", "1998-06-01T04:00:00.000", "2025-04-03T01:03:51.193", "A Unix account has a guessable password."),
	(535, "CVE-1999-0508", "1998-06-01T04:00:00.000", "2025-04-03T01:03:51.193", "An account on a router, firewall, or other network device has a default, null, blank, or missing password."),
	(536, "CVE-1999-1443", "1998-06-02T04:00:00.000", "2025-04-03T01:03:51.193", "Micah Software Full Armor Network Configurator and Zero Administration allow local users with physical access to bypass the desktop protection by (1) using <CTRL><ALT><DEL> and kill the process using the task manager, (2) booting the system from a separate disk, or (3) interrupting certain processes that execute while the system is booting."),
	(537, "CVE-1999-1151", "1998-06-03T04:00:00.000", "2025-04-03T01:03:51.193", "Compaq/Microcom 6000 Access Integrator does not cause a session timeout after prompting for a username or password, which allows remote attackers to cause a denial of service by connecting to the integrator without providing a username or password."),
	(538, "CVE-1999-1152", "1998-06-03T04:00:00.000", "2025-04-03T01:03:51.193", "Compaq/Microcom 6000 Access Integrator does not disconnect a client after a certain number of failed login attempts, which allows remote attackers to guess usernames or passwords via a brute force attack."),
	(539, "CVE-1999-0008", "1998-06-08T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in NIS+, in Sun\'s rpc.nisd program."),
	(540, "CVE-1999-0054", "1998-06-10T04:00:00.000", "2025-04-03T01:03:51.193", "Sun\'s ftpd daemon can be subjected to a denial of service."),
	(541, "CVE-1999-1178", "1998-06-10T04:00:00.000", "2025-04-03T01:03:51.193", "Sambar Server 4.1 beta allows remote attackers to obtain sensitive information about the server via an HTTP request for the dumpenv.pl script."),
	(542, "CVE-1999-1271", "1998-06-11T04:00:00.000", "2025-04-03T01:03:51.193", "Macromedia Dreamweaver uses weak encryption to store FTP passwords, which could allow local users to easily decrypt the passwords of other users."),
	(543, "CVE-1999-1480", "1998-06-11T04:00:00.000", "2025-04-03T01:03:51.193", "(1) acledit and (2) aclput in AIX 4.3 allow local users to create or modify files via a symlink attack."),
	(544, "CVE-1999-1555", "1998-06-11T04:00:00.000", "2025-04-03T01:03:51.193", "Cheyenne InocuLAN Anti-Virus Server in Inoculan 4.0 before Service Pack 2 creates an update directory with \"EVERYONE FULL CONTROL\" permissions, which allows local users to cause Inoculan\'s antivirus update feature to install a Trojan horse dll."),
	(545, "CVE-1999-1085", "1998-06-12T04:00:00.000", "2025-04-03T01:03:51.193", "SSH 1.2.25, 1.2.23, and other versions, when used in in CBC (Cipher Block Chaining) or CFB (Cipher Feedback 64 bits) modes, allows remote attackers to insert arbitrary data into an existing stream between an SSH client and server by using a known plaintext attack and computing a valid CRC-32 checksum for the packet, aka the \"SSH insertion attack.\""),
	(546, "CVE-1999-0783", "1998-06-16T04:00:00.000", "2025-04-03T01:03:51.193", "FreeBSD allows local users to conduct a denial of service by creating a hard link from a device special file to a file on an NFS file system."),
	(547, "CVE-1999-1442", "1998-06-22T04:00:00.000", "2025-04-03T01:03:51.193", "Bug in AMD K6 processor on Linux 2.0.x and 2.1.x kernels allows local users to cause a denial of service (crash) via a particular sequence of instructions, possibly related to accessing addresses outside of segments."),
	(548, "CVE-1999-1479", "1998-06-24T04:00:00.000", "2025-04-03T01:03:51.193", "The textcounter.pl by Matt Wright allows remote attackers to execute arbitrary commands via shell metacharacters."),
	(549, "CVE-1999-0007", "1998-06-26T04:00:00.000", "2025-04-03T01:03:51.193", "Information from SSL-encrypted sessions via PKCS #1."),
	(550, "CVE-1999-1036", "1998-06-26T04:00:00.000", "2025-04-03T01:03:51.193", "COPS 1.04 allows local users to overwrite or create arbitrary files via a symlink attack on temporary files in (1) res_diff, (2) ca.src, and (3) mail.chk."),
	(551, "CVE-1999-1037", "1998-06-26T04:00:00.000", "2025-04-03T01:03:51.193", "rex.satan in SATAN 1.1.1 allows local users to overwrite arbitrary files via a symlink attack on the /tmp/rex.$$ file."),
	(552, "CVE-1999-1038", "1998-06-26T04:00:00.000", "2025-04-03T01:03:51.193", "Tiger 2.2.3 allows local users to overwrite arbitrary files via a symlink attack on various temporary files in Tiger\'s default working directory, as defined by the WORKDIR variable."),
	(553, "CVE-1999-0797", "1998-06-29T04:00:00.000", "2025-04-03T01:03:51.193", "NIS finger allows an attacker to conduct a denial of service via a large number of finger requests, resulting in a large number of NIS queries."),
	(554, "CVE-1999-1556", "1998-06-29T04:00:00.000", "2025-04-03T01:03:51.193", "Microsoft SQL Server 6.5 uses weak encryption for the password for the SQLExecutiveCmdExec account and stores it in an accessible portion of the registry, which could allow local users to gain privileges by reading and decrypting the CmdExecAccount value."),
	(555, "CVE-1999-1150", "1998-06-30T04:00:00.000", "2025-04-03T01:03:51.193", "Livingston Portmaster routers running ComOS use the same initial sequence number (ISN) for TCP connections, which allows remote attackers to conduct spoofing and hijack TCP sessions."),
	(556, "CVE-1999-1441", "1998-06-30T04:00:00.000", "2025-04-03T01:03:51.193", "Linux 2.0.34 does not properly prevent users from sending SIGIO signals to arbitrary processes, which allows local users to cause a denial of service by sending SIGIO to processes that do not catch it."),
	(557, "CVE-1999-0313", "1998-07-01T04:00:00.000", "2025-04-03T01:03:51.193", "disk_bandwidth on SGI IRIX 6.4 S2MP for Origin/Onyx2 allows local users to gain root access using relative pathnames."),
	(558, "CVE-1999-0314", "1998-07-01T04:00:00.000", "2025-04-03T01:03:51.193", "ioconfig on SGI IRIX 6.4 S2MP for Origin/Onyx2 allows local users to gain root access using relative pathnames."),
	(559, "CVE-1999-0494", "1998-07-01T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in WinGate proxy through a buffer overflow in POP3."),
	(560, "CVE-1999-1202", "1998-07-03T04:00:00.000", "2025-04-03T01:03:51.193", "StarTech (1) POP3 proxy server and (2) telnet server allows remote attackers to cause a denial of service via a long USER command."),
	(561, "CVE-1999-1409", "1998-07-03T04:00:00.000", "2025-04-03T01:03:51.193", "The at program in IRIX 6.2 and NetBSD 1.3.2 and earlier allows local users to read portions of arbitrary files by submitting the file to at with the -f argument, which generates error messages that at sends to the user via e-mail."),
	(562, "CVE-1999-1574", "1998-07-06T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the lex routines of nslookup for AIX 4.3 may allow attackers to cause a core dump and possibly execute arbitrary code via \"long input strings.\""),
	(563, "CVE-1999-1437", "1998-07-07T04:00:00.000", "2025-04-03T01:03:51.193", "ePerl 2.2.12 allows remote attackers to read arbitrary files and possibly execute certain commands by specifying a full pathname of the target file as an argument to bar.phtml."),
	(564, "CVE-1999-1436", "1998-07-08T04:00:00.000", "2025-04-03T01:03:51.193", "Ray Chan WWW Authorization Gateway 0.1 CGI program allows remote attackers to execute arbitrary commands via shell metacharacters in the \"user\" parameter."),
	(565, "CVE-1999-0102", "1998-07-09T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in SLmail 3.x allows attackers to execute commands using a large FROM line."),
	(566, "CVE-1999-1435", "1998-07-10T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in libsocks5 library of Socks 5 (socks5) 1.0r5 allows local users to gain privileges via long environmental variables."),
	(567, "CVE-1999-1270", "1998-07-11T04:00:00.000", "2025-04-03T01:03:51.193", "KMail in KDE 1.0 provides a PGP passphrase as a command line argument to other programs, which could allow local users to obtain the passphrase and compromise the PGP keys of other users by viewing the arguments via programs that list process information, such as ps."),
	(568, "CVE-1999-1434", "1998-07-13T04:00:00.000", "2025-04-03T01:03:51.193", "login in Slackware Linux 3.2 through 3.5 does not properly check for an error when the /etc/group file is missing, which prevents it from dropping privileges, causing it to assign root privileges to any local user who logs on to the server."),
	(569, "CVE-1999-0006", "1998-07-14T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in POP servers based on BSD/Qualcomm\'s qpopper allows remote attackers to gain root access using a long PASS command."),
	(570, "CVE-1999-0213", "1998-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "libnsl in Solaris allowed an attacker to perform a denial of service of rpcbind."),
	(571, "CVE-1999-1297", "1998-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "cmdtool in OpenWindows 3.0 and XView 3.0 in SunOS 4.1.4 and earlier allows attackers with physical access to the system to display unechoed characters (such as those from password prompts) via the L2/AGAIN key."),
	(572, "CVE-1999-1433", "1998-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "HP JetAdmin D.01.09 on Solaris allows local users to change the permissions of arbitrary files via a symlink attack on the /tmp/jetadmin.log file."),
	(573, "CVE-1999-1582", "1998-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "By design, the \"established\" command on the Cisco PIX firewall allows connections from one host to arbitrary ports of a target host if an alternative conduit has already been allowed, which can cause administrators to configure less restrictive access controls than intended if they do not understand this functionality."),
	(574, "CVE-1999-0263", "1998-07-16T04:00:00.000", "2025-04-03T01:03:51.193", "Solaris SUNWadmap can be exploited to obtain root access."),
	(575, "CVE-1999-1149", "1998-07-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in CSM Proxy 4.1 allows remote attackers to cause a denial of service (crash) via a long string to the FTP port."),
	(576, "CVE-1999-1432", "1998-07-16T04:00:00.000", "2025-04-03T01:03:51.193", "Power management (Powermanagement) on Solaris 2.4 through 2.6 does not start the xlock process until after the sys-suspend has completed, which allows an attacker with physical access to input characters to the last active application from the keyboard for a short period after the system is restoring, which could lead to increased privileges."),
	(577, "CVE-1999-1558", "1998-07-16T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in loginout in Digital OpenVMS 7.1 and earlier allows unauthorized access when external authentication is enabled."),
	(578, "CVE-1999-0005", "1998-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "Arbitrary command execution via IMAP buffer overflow in authenticate command."),
	(579, "CVE-1999-1200", "1998-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "Vintra SMTP MailServer allows remote attackers to cause a denial of service via a malformed \"EXPN *@\" command."),
	(580, "CVE-1999-1420", "1998-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "NBase switches NH2012, NH2012R, NH2015, and NH2048 have a back door password that cannot be disabled, which allows remote attackers to modify the switch\'s configuration."),
	(581, "CVE-1999-1421", "1998-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "NBase switches NH208 and NH215 run a TFTP server which allows remote attackers to send software updates to modify the switch or cause a denial of service (crash) by guessing the target filenames, which have default names."),
	(582, "CVE-1999-1070", "1998-07-25T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ping CGI program in Xylogics Annex terminal service allows remote attackers to cause a denial of service via a long query parameter."),
