	(586, "CVE-1999-1448", "1998-07-29T04:00:00.000", "2025-04-03T01:03:51.193", "Eudora and Eudora Light before 3.05 allows remote attackers to cause a crash and corrupt the user\'s mailbox via an e-mail message with certain dates, such as (1) dates before 1970, which cause a Divide By Zero error, or (2) dates that are 100 years after the current date, which causes a segmentation fault."),
	(587, "CVE-1999-1136", "1998-07-30T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Predictive on HP-UX 11.0 and earlier, and MPE/iX 5.5 and earlier, allows attackers to compromise data transfer for Predictive messages (using e-mail or modem) between customer and Response Center Predictive systems."),
	(588, "CVE-1999-0269", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "Netscape Enterprise servers may list files through the PageServices query."),
	(589, "CVE-1999-0288", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "The WINS server in Microsoft Windows NT 4.0 before SP4 allows remote attackers to cause a denial of service (process termination) via invalid UDP frames to port 137 (NETBIOS Name Service), as demonstrated via a flood of random packets."),
	(590, "CVE-1999-0333", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "HP OpenView Omniback allows remote execution of commands as root via spoofing, and local users can gain root access via a symlink attack."),
	(591, "CVE-1999-0339", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the libauth library in Solaris allows local users to gain additional privileges, possibly root access."),
	(592, "CVE-1999-0344", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "NT users can gain debug-level access on a system process using the Sechole exploit."),
	(593, "CVE-1999-0516", "1998-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "An SNMP community name is guessable."),
	(594, "CVE-1999-0062", "1998-08-03T04:00:00.000", "2025-04-03T01:03:51.193", "The chpass command in OpenBSD allows a local user to gain root access through file descriptor leakage."),
	(595, "CVE-1999-0262", "1998-08-04T04:00:00.000", "2025-04-03T01:03:51.193", "Hylafax faxsurvey CGI script on Linux allows remote attackers to execute arbitrary commands via shell metacharacters in the query string."),
	(596, "CVE-1999-1199", "1998-08-07T04:00:00.000", "2025-04-03T01:03:51.193", "Apache WWW server 1.3.1 and earlier allows remote attackers to cause a denial of service (resource exhaustion) via a large number of MIME headers with the same name, aka the \"sioux\" vulnerability."),
	(597, "CVE-1999-0159", "1998-08-12T04:00:00.000", "2025-08-27T19:15:33.120", "Attackers can crash a Cisco IOS router or device, provided they can get to an interactive prompt (such as a login).  This applies to some IOS 9.x, 10.x, and 11.x releases."),
	(598, "CVE-1999-1283", "1998-08-14T04:00:00.000", "2025-04-03T01:03:51.193", "Opera 3.2.1 allows remote attackers to cause a denial of service (application crash) via a URL that contains an extra / in the http:// tag."),
	(599, "CVE-1999-0157", "1998-08-18T04:00:00.000", "2025-04-03T01:03:51.193", "Cisco PIX firewall and CBAC IP fragmentation attack results in a denial of service."),
