	(601, "CVE-1999-1417", "1998-08-23T04:00:00.000", "2025-04-03T01:03:51.193", "Format string vulnerability in AnswerBook2 (AB2) web server dwhttpd 3.1a4 allows remote attackers to cause a denial of service and possibly execute arbitrary commands via encoded % characters in an HTTP request, which is improperly logged."),
	(602, "CVE-1999-1041", "1998-08-27T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in mscreen on SCO OpenServer 5.0 and SCO UNIX 3.2v4 allows a local user to gain root access via (1) a long TERM environmental variable and (2) a long entry in the .mscreenrc file."),
	(603, "CVE-1999-0065", "1998-08-31T04:00:00.000", "2025-04-03T01:03:51.193", "Multiple buffer overflows in how dtmail handles attachments allows a remote attacker to execute commands."),
	(604, "CVE-1999-0158", "1998-08-31T04:00:00.000", "2025-04-03T01:03:51.193", "Cisco PIX firewall manager (PFM) on Windows NT allows attackers to connect to port 8080 on the PFM server and retrieve any file whose name and location is known."),
	(605, "CVE-1999-0162", "1998-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "The \"established\" keyword in some Cisco IOS software allowed an attacker to bypass filtering."),
	(606, "CVE-1999-0302", "1998-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "SunOS/Solaris FTP clients can be forced to execute arbitrary commands from a malicious FTP server."),
	(607, "CVE-1999-0310", "1998-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "SSH 1.2.25 on HP-UX allows access to new user accounts."),
	(608, "CVE-1999-0792", "1998-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "ROUTERmate has a default SNMP community name which allows remote attackers to modify its configuration."),
	(609, "CVE-1999-1292", "1998-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in web administration feature of Kolban Webcam32 4.8.3 and earlier allows remote attackers to execute arbitrary commands via a long URL."),
	(610, "CVE-1999-0779", "1998-09-03T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in HP-UX SharedX recserv program."),
	(611, "CVE-1999-0930", "1998-09-03T04:00:00.000", "2025-04-03T01:03:51.193", "wwwboard allows a remote attacker to delete message board articles via a malformed argument."),
	(612, "CVE-1999-0871", "1998-09-04T04:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.0 and 4.01 allow a remote attacker to read files via IE\'s cross frame security, aka the \"Cross Frame Navigate\" vulnerability."),
	(613, "CVE-1999-1048", "1998-09-05T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in bash 2.0.0, 1.4.17, and other versions allows local attackers to gain privileges by creating an extremely large directory name, which is inserted into the password prompt via the \\w option in the PS1 environmental variable when another user changes into that directory."),
	(614, "CVE-1999-0056", "1998-09-09T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Sun\'s ping program can give root access to local users."),
	(615, "CVE-1999-0897", "1998-09-09T04:00:00.000", "2025-04-03T01:03:51.193", "iChat ROOMS Webserver allows remote attackers to read arbitrary files via a .. (dot dot) attack."),
