	(1116, "CVE-1999-1478", "1999-07-06T04:00:00.000", "2025-04-03T01:03:51.193", "The Sun HotSpot Performance Engine VM allows a remote attacker to cause a denial of service on any server running HotSpot via a URL that includes the [ character."),
	(1117, "CVE-1999-1537", "1999-07-07T04:00:00.000", "2025-04-03T01:03:51.193", "IIS 3.x and 4.x does not distinguish between pages requiring encryption and those that do not, which allows remote attackers to cause a denial of service (resource exhaustion) via SSL requests to the HTTPS port for normally unencrypted files, which will cause IIS to perform extra work to send the files over SSL."),
	(1118, "CVE-1999-0809", "1999-07-09T04:00:00.000", "2025-04-03T01:03:51.193", "Netscape Communicator 4.x with Javascript enabled does not warn a user of cookie settings, even if they have selected the option to \"Only accept cookies originating from the same server as the page being viewed\"."),
	(1119, "CVE-1999-1543", "1999-07-10T04:00:00.000", "2025-04-03T01:03:51.193", "MacOS uses weak encryption for passwords that are stored in the Users & Groups Data File."),
	(1120, "CVE-1999-1166", "1999-07-11T04:00:00.000", "2025-04-03T01:03:51.193", "Linux 2.0.37 does not properly encode the Custom segment limit, which allows local users to gain root privileges by accessing and modifying kernel memory."),
	(1121, "CVE-1999-1460", "1999-07-13T04:00:00.000", "2025-04-03T01:03:51.193", "BMC PATROL SNMP Agent before 3.2.07 allows local users to create arbitrary world-writeable files as root by specifying the target file as the second argument to the snmpmagt program."),
	(1122, "CVE-1999-1545", "1999-07-14T04:00:00.000", "2025-04-03T01:03:51.193", "Joe\'s Own Editor (joe) 2.8 sets the world-readable permission on its crash-save file, DEADJOE, which could allow local users to read files that were being edited by other users."),
	(1123, "CVE-1999-1086", "1999-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "Novell 5 and earlier, when running over IPX with a packet signature level less than 3, allows remote attackers to gain administrator privileges by spoofing the MAC address in IPC fragmented packets that make NetWare Core Protocol (NCP) calls."),
	(1124, "CVE-1999-1518", "1999-07-15T04:00:00.000", "2025-04-03T01:03:51.193", "Operating systems with shared memory implementations based on BSD 4.4 code allow a user to conduct a denial of service and bypass memory limits (e.g., as specified with rlimits) using mmap or shmget to allocate memory and cause page faults."),
	(1125, "CVE-1999-0692", "1999-07-19T04:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of the Array Services daemon (arrayd) disables authentication, allowing remote users to gain root privileges."),
	(1126, "CVE-1999-1011", "1999-07-19T04:00:00.000", "2025-04-03T01:03:51.193", "The Remote Data Service (RDS) DataFactory component of Microsoft Data Access Components (MDAC) in IIS 3.x and 4.x exposes unsafe methods, which allows remote attackers to execute arbitrary commands."),
	(1127, "CVE-1999-1378", "1999-07-19T04:00:00.000", "2025-04-03T01:03:51.193", "dbmlparser.exe CGI guestbook program does not perform a chroot operation properly, which allows remote attackers to read arbitrary files."),
	(1128, "CVE-1999-0721", "1999-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in Windows NT Local Security Authority (LSA) through a malformed LSA request."),
	(1129, "CVE-1999-1535", "1999-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in AspUpload.dll in Persits Software AspUpload before 1.4.0.2 allows remote attackers to cause a denial of service, and possibly execute arbitrary commands, via a long argument in the HTTP request."),
	(1130, "CVE-1999-1560", "1999-07-20T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in a script in Texas A&M University (TAMU) Tiger allows local users to execute arbitrary commands as the Tiger user, usually root."),
	(1131, "CVE-1999-0810", "1999-07-21T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in Samba NETBIOS name service daemon (nmbd)."),
	(1132, "CVE-1999-0811", "1999-07-21T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Samba smbd program via a malformed message command."),
	(1133, "CVE-1999-1165", "1999-07-21T04:00:00.000", "2025-04-03T01:03:51.193", "GNU fingerd 1.37 does not properly drop privileges before accessing user information, which could allow local users to (1) gain root privileges via a malicious program in the .fingerrc file, or (2) read arbitrary files via symbolic links from .plan, .forward, or .project files."),
	(1134, "CVE-1999-1338", "1999-07-21T04:00:00.000", "2025-04-03T01:03:51.193", "Delegate proxy 5.9.3 and earlier creates files and directories in the DGROOT with world-writable permissions."),
	(1135, "CVE-1999-0224", "1999-07-23T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in Windows NT messenger service through a long username."),
	(1136, "CVE-1999-0710", "1999-07-25T04:00:00.000", "2025-04-03T01:03:51.193", "The Squid package in Red Hat Linux 5.2 and 6.0, and other distributions, installs cachemgr.cgi in a public web directory, which allows remote attackers to use it as an intermediary to connect to other systems."),
	(1137, "CVE-1999-1018", "1999-07-27T04:00:00.000", "2025-04-03T01:03:51.193", "IPChains in Linux kernels 2.2.10 and earlier does not reassemble IP fragments before checking the header information, which allows a remote attacker to bypass the filtering rules using several fragments with 0 offsets."),
	(1138, "CVE-1999-1017", "1999-07-28T04:00:00.000", "2025-04-03T01:03:51.193", "Seattle Labs Emurl 2.0, and possibly earlier versions, stores e-mail attachments in a specific directory with scripting enabled, which allows a malicious ASP file attachment to execute when the recipient opens the message."),
	(1139, "CVE-2000-0323", "1999-07-28T04:00:00.000", "2025-04-03T01:03:51.193", "The Microsoft Jet database engine allows an attacker to modify text files via a database query, aka the \"Text I-ISAM\" vulnerability."),
	(1140, "CVE-1999-0700", "1999-07-29T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Microsoft Phone Dialer (dialer.exe), via a malformed dialer entry in the dialer.ini file."),
	(1141, "CVE-1999-0770", "1999-07-29T04:00:00.000", "2025-04-03T01:03:51.193", "Firewall-1 sets a long timeout for connections that begin with ACK or other packets except SYN, allowing an attacker to conduct a denial of service via a large number of connection attempts to unresponsive systems."),
	(1142, "CVE-1999-1078", "1999-07-29T04:00:00.000", "2025-04-03T01:03:51.193", "WS_FTP Pro 6.0 uses weak encryption for passwords in its initialization files, which allows remote attackers to easily decrypt the passwords and gain privileges."),
	(1143, "CVE-1999-0683", "1999-07-30T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in Gauntlet Firewall via a malformed ICMP packet."),
	(1144, "CVE-1999-1130", "1999-07-30T04:00:00.000", "2025-04-03T01:03:51.193", "Default configuration of the search engine in Netscape Enterprise Server 3.5.1, and possibly other versions, allows remote attackers to read the source of JHTML files by specifying a search command using the HTML-tocrec-demo1.pat pattern file."),
	(1145, "CVE-1999-1227", "1999-07-30T04:00:00.000", "2025-04-03T01:03:51.193", "Ethereal allows local users to overwrite arbitrary files via a symlink attack on the packet capture file."),
	(1146, "CVE-1999-1536", "1999-07-30T04:00:00.000", "2025-04-03T01:03:51.193", ".sbstart startup script in AcuShop Salesbuilder is world writable, which allows local users to gain privileges by appending commands to the file."),
	(1147, "CVE-1999-0672", "1999-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Fujitsu Chocoa IRC client via IRC channel topics."),
	(1148, "CVE-1999-1337", "1999-08-01T04:00:00.000", "2025-04-03T01:03:51.193", "FTP client in Midnight Commander (mc) before 4.5.11 stores usernames and passwords for visited sites in plaintext in the world-readable history file, which allows other local users to gain privileges."),
	(1149, "CVE-1999-0671", "1999-08-03T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ToxSoft NextFTP client through CWD command."),
	(1150, "CVE-1999-0677", "1999-08-03T04:00:00.000", "2025-04-03T01:03:51.193", "The WebRamp web administration utility has a default password."),
	(1151, "CVE-1999-0703", "1999-08-03T04:00:00.000", "2025-04-03T01:03:51.193", "OpenBSD, BSDI, and other Unix operating systems allow users to set chflags and fchflags on character and block devices."),
	(1152, "CVE-1999-0719", "1999-08-05T04:00:00.000", "2025-04-03T01:03:51.193", "The Guile plugin for the Gnumeric spreadsheet package allows attackers to execute arbitrary code."),
	(1153, "CVE-1999-0913", "1999-08-05T04:00:00.000", "2025-04-03T01:03:51.193", "dfire.cgi script in Dragon-Fire IDS allows remote users to execute commands via shell metacharacters."),
	(1154, "CVE-1999-0682", "1999-08-06T04:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Exchange 5.5 allows a remote attacker to relay email (i.e. spam) using encapsulated SMTP addresses, even if the anti-relaying features are enabled."),
	(1155, "CVE-1999-0727", "1999-08-06T04:00:00.000", "2025-04-03T01:03:51.193", "A kernel leak in the OpenBSD kernel allows IPsec packets to be sent unencrypted."),
	(1156, "CVE-1999-1524", "1999-08-07T04:00:00.000", "2025-04-03T01:03:51.193", "FlowPoint DSL router firmware versions prior to 3.0.8 allows a remote attacker to exploit a password recovery feature from the network and conduct brute force password guessing, instead of limiting the feature to the serial console port."),
	(1157, "CVE-1999-0673", "1999-08-08T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ALMail32 POP3 client via From: or To: headers."),
	(1158, "CVE-1999-0722", "1999-08-08T04:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of Cobalt RaQ2 servers allows remote users to install arbitrary software packages."),
	(1159, "CVE-1999-0674", "1999-08-09T04:00:00.000", "2025-04-03T01:03:51.193", "The BSD profil system call allows a local user to modify the internal data space of a program via profiling and execve."),
	(1160, "CVE-1999-0675", "1999-08-09T04:00:00.000", "2025-04-03T01:03:51.193", "Check Point FireWall-1 can be subjected to a denial of service via UDP packets that are sent through VPN-1 to port 0 of a host."),
	(1161, "CVE-1999-0676", "1999-08-09T04:00:00.000", "2025-04-03T01:03:51.193", "sdtcm_convert in Solaris 2.6 allows a local user to overwrite sensitive files via a symlink attack."),
	(1162, "CVE-1999-0680", "1999-08-09T04:00:00.000", "2025-04-03T01:03:51.193", "Windows NT Terminal Server performs extra work when a client opens a new connection but before it is authenticated, allowing for a denial of service."),
	(1163, "CVE-1999-0813", "1999-08-10T04:00:00.000", "2025-04-03T01:03:51.193", "Cfingerd with ALLOW_EXECUTION enabled does not properly drop privileges when it executes a program on behalf of the user, allowing local users to gain root privileges."),
	(1164, "CVE-1999-0694", "1999-08-11T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in AIX ptrace system call allows local users to crash the system."),
	(1165, "CVE-1999-0814", "1999-08-11T04:00:00.000", "2025-04-03T01:03:51.193", "Red Hat pump DHCP client allows remote attackers to gain root access in some configurations."),
	(1166, "CVE-1999-0861", "1999-08-11T04:00:00.000", "2025-04-03T01:03:51.193", "Race condition in the SSL ISAPI filter in IIS and other servers may leak information in plaintext."),
	(1167, "CVE-1999-0867", "1999-08-11T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in IIS 4.0 via a flood of HTTP requests with malformed headers."),
	(1168, "CVE-1999-0875", "1999-08-11T04:00:00.000", "2025-04-03T01:03:51.193", "DHCP clients with ICMP Router Discovery Protocol (IRDP) enabled allow remote attackers to modify their default routes."),
	(1169, "CVE-1999-0724", "1999-08-12T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in OpenBSD procfs and fdescfs file systems via uio_offset in the readdir() function."),
	(1170, "CVE-1999-1336", "1999-08-12T04:00:00.000", "2025-04-03T01:03:51.193", "3Com HiPer Access Router Card (HiperARC) 4.0 through 4.2.29 allows remote attackers to cause a denial of service (reboot) via a flood of IAC packets to the telnet port."),
	(1171, "CVE-1999-0679", "1999-08-13T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in hybrid-6 IRC server commonly used on EFnet allows remote attackers to execute commands via m_invite invite option."),
	(1172, "CVE-1999-0746", "1999-08-16T04:00:00.000", "2025-04-03T01:03:51.193", "A default configuration of in.identd in SuSE Linux waits 120 seconds between requests, allowing a remote attacker to conduct a denial of service."),
	(1173, "CVE-1999-0749", "1999-08-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Microsoft Telnet client in Windows 95 and Windows 98 via a malformed Telnet argument."),
	(1174, "CVE-1999-0888", "1999-08-16T04:00:00.000", "2025-04-03T01:03:51.193", "dbsnmp in Oracle Intelligent Agent allows local users to gain privileges by setting the ORACLE_HOME environmental variable, which dbsnmp uses to find the nmiconf.tcl script."),
	(1175, "CVE-1999-0753", "1999-08-17T04:00:00.000", "2025-04-03T01:03:51.193", "The w3-msql CGI script provided with Mini SQL allows remote attackers to view restricted directories."),
	(1176, "CVE-1999-0745", "1999-08-18T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Source Code Browser Program Database Name Server Daemon (pdnsd) for the IBM AIX C Set ++ compiler."),
	(1177, "CVE-1999-0747", "1999-08-18T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in BSDi Symmetric Multiprocessing (SMP) when an fstat call is made when the system has a high CPU load.");
INSERT INTO `cvss_data` (`id`, `cve_id`, `published_date`, `last_modified`, `description`) VALUES
	(1178, "CVE-1999-0725", "1999-08-19T04:00:00.000", "2025-04-03T01:03:51.193", "When IIS is run with a default language of Chinese, Korean, or Japanese, it allows a remote attacker to view the source code of certain files, a.k.a. \"Double Byte Code Page\"."),
	(1179, "CVE-1999-0732", "1999-08-19T04:00:00.000", "2025-04-03T01:03:51.193", "The logging facility of the Debian smtp-refuser package allows local users to delete arbitrary files using symbolic links."),
	(1180, "CVE-1999-0734", "1999-08-19T04:00:00.000", "2025-04-03T01:03:51.193", "A default configuration of CiscoSecure Access Control Server (ACS) allows remote users to modify the server database without authentication."),
	(1181, "CVE-1999-0740", "1999-08-19T04:00:00.000", "2025-04-03T01:03:51.193", "Remote attackers can cause a denial of service on Linux in.telnetd telnet daemon through a malformed TERM environmental variable."),
	(1182, "CVE-1999-0741", "1999-08-19T04:00:00.000", "2025-04-03T01:03:51.193", "QMS CrownNet Unix Utilities for 2060 allows root to log on without a password."),
	(1183, "CVE-1999-0743", "1999-08-20T04:00:00.000", "2025-04-03T01:03:51.193", "Trn allows local users to overwrite other users\' files via symlinks."),
	(1184, "CVE-1999-1561", "1999-08-20T04:00:00.000", "2025-04-03T01:03:51.193", "Nullsoft SHOUTcast server stores the administrative password in plaintext in a configuration file (sc_serv.conf), which could allow a local user to gain administrative privileges on the server."),
	(1185, "CVE-1999-1565", "1999-08-20T04:00:00.000", "2025-04-03T01:03:51.193", "Man2html 2.1 and earlier allows local users to overwrite arbitrary files via a symlink attack on a temporary file."),
	(1186, "CVE-2000-0325", "1999-08-20T04:00:00.000", "2025-04-03T01:03:51.193", "The Microsoft Jet database engine allows an attacker to execute commands via a database query, aka the \"VBA Shell\" vulnerability."),
	(1187, "CVE-2000-1206", "1999-08-20T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Apache httpd before 1.3.11, when configured for mass virtual hosting using mod_rewrite, or mod_vhost_alias in Apache 1.3.9, allows remote attackers to retrieve arbitrary files."),
	(1188, "CVE-1999-0668", "1999-08-21T04:00:00.000", "2025-04-03T01:03:51.193", "The scriptlet.typelib ActiveX control is marked as \"safe for scripting\" for Internet Explorer, which allows a remote attacker to execute arbitrary commands as demonstrated by Bubbleboy."),
	(1189, "CVE-2000-0355", "1999-08-21T04:00:00.000", "2025-04-03T01:03:51.193", "pg and pb in SuSE pbpg 1.x package allows an attacker to read arbitrary files."),
	(1190, "CVE-1999-0878", "1999-08-22T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in WU-FTPD and related FTP servers allows remote attackers to gain root privileges via MAPPING_CHDIR."),
	(1191, "CVE-1999-1064", "1999-08-22T04:00:00.000", "2025-04-03T01:03:51.193", "Multiple buffer overflows in WindowMaker 0.52 through 0.60.0 allow attackers to cause a denial of service and possibly execute arbitrary commands by executing WindowMaker with a long program name (argv[0])."),
	(1192, "CVE-2000-0374", "1999-08-22T04:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of kdm in Caldera and Mandrake Linux, and possibly other distributions, allows XDMCP connections from any host, which allows remote attackers to obtain sensitive information or bypass additional access restrictions."),
	(1193, "CVE-1999-0720", "1999-08-23T04:00:00.000", "2025-04-03T01:03:51.193", "The pt_chown command in Linux allows local users to modify TTY terminal devices that belong to other users."),
	(1194, "CVE-1999-1052", "1999-08-24T04:00:00.000", "2025-04-03T01:03:51.193", "Microsoft FrontPage stores form results in a default location in /_private/form_results.txt, which is world-readable and accessible in the document root, which allows remote attackers to read possibly sensitive information submitted by other users."),
	(1195, "CVE-2000-0328", "1999-08-24T04:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 generates predictable random TCP initial sequence numbers (ISN), which allows remote attackers to perform spoofing and session hijacking."),
	(1196, "CVE-1999-0768", "1999-08-25T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Vixie Cron on Red Hat systems via the MAILTO environmental variable."),
	(1197, "CVE-1999-0769", "1999-08-25T04:00:00.000", "2025-04-03T01:03:51.193", "Vixie Cron on Linux systems allows local users to set parameters of sendmail commands via the MAILTO environmental variable."),
	(1198, "CVE-1999-0872", "1999-08-25T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Vixie cron allows local users to gain root access via a long MAILTO environment variable in a crontab file."),
	(1199, "CVE-1999-1235", "1999-08-25T04:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 5.0 records the username and password for FTP servers in the URL history, which could allow (1) local users to read the information from another user\'s index.dat, or (2) people who are physically observing (\"shoulder surfing\") another user to read the information from the status bar when the user moves the mouse over a link."),
	(1200, "CVE-1999-0939", "1999-08-26T04:00:00.000", "2025-04-03T01:03:51.193", "Denial of service in Debian IRC Epic/epic4 client via a long string."),
	(1201, "CVE-1999-0911", "1999-08-27T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ProFTPD, wu-ftpd, and beroftpd allows remote attackers to gain root access via a series of MKD and CWD commands that create nested directories."),
	(1202, "CVE-1999-1016", "1999-08-27T04:00:00.000", "2025-04-03T01:03:51.193", "Microsoft HTML control as used in (1) Internet Explorer 5.0, (2) FrontPage Express, (3) Outlook Express 5, and (4) Eudora, and possibly others, allows remote malicious web site or HTML emails to cause a denial of service (100% CPU consumption) via large HTML form fields such as text inputs in a table cell."),
	(1203, "CVE-1999-1354", "1999-08-30T04:00:00.000", "2025-04-03T01:03:51.193", "E-mail client in Softarc FirstClass Internet Server 5.506 and earlier stores usernames and passwords in cleartext in the files (1) home.fc for version 5.506, (2) network.fc for version 3.5, or (3) FCCLIENT.LOG when logging is enabled."),
	(1204, "CVE-1999-1513", "1999-08-30T04:00:00.000", "2025-04-03T01:03:51.193", "Management information base (MIB) for a 3Com SuperStack II hub running software version 2.10 contains an object identifier (.1.3.6.1.4.1.43.10.4.2) that is accessible by a read-only community string, but lists the entire table of community strings, which could allow attackers to conduct unauthorized activities."),
	(1205, "CVE-1999-0774", "1999-08-31T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflows in Mars NetWare Emulation (NWE, mars_nwe) package via long directory names."),
	(1206, "CVE-1999-1515", "1999-08-31T04:00:00.000", "2025-04-03T01:03:51.193", "A non-default configuration in TenFour TFS Gateway 4.0 allows an attacker to cause a denial of service via messages with incorrect sender and recipient addresses, which causes the gateway to continuously try to return the message every 10 seconds."),
	(1207, "CVE-1999-0669", "1999-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "The Eyedog ActiveX control is marked as \"safe for scripting\" for Internet Explorer, which allows a remote attacker to execute arbitrary commands as demonstrated by Bubbleboy."),
	(1208, "CVE-1999-0670", "1999-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the Eyedog ActiveX control allows a remote attacker to execute arbitrary commands."),
	(1209, "CVE-1999-0705", "1999-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in INN inews program."),
	(1210, "CVE-1999-0891", "1999-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "The \"download behavior\" in Internet Explorer 5 allows remote attackers to read arbitrary files via a server-side redirect."),
	(1211, "CVE-1999-1129", "1999-09-01T04:00:00.000", "2025-04-03T01:03:51.193", "Cisco Catalyst 2900 Virtual LAN (VLAN) switches allow remote attackers to inject 802.1q frames into another VLAN by forging the VLAN identifier in the trunking tag."),
	(1212, "CVE-1999-0685", "1999-09-02T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Netscape Communicator via EMBED tags in the pluginspage option."),
	(1213, "CVE-1999-1356", "1999-09-02T04:00:00.000", "2025-04-03T01:03:51.193", "Compaq Integration Maintenance Utility as used in Compaq Insight Manager agent before SmartStart 4.50 modifies the legal notice caption (LegalNoticeCaption) and text (LegalNoticeText) in Windows NT, which could produce a legal notice that is in violation of the security policy."),
	(1214, "CVE-1999-1516", "1999-09-02T04:00:00.000", "2025-04-03T01:03:51.193", "A buffer overflow in TenFour TFS Gateway SMTP mail server 3.2 allows an attacker to crash the mail server and possibly execute arbitrary code by offering more than 128 bytes in a MAIL FROM string."),
