	(1515, "CVE-2000-0076", "1999-12-30T05:00:00.000", "2025-04-03T01:03:51.193", "nviboot boot script in the Debian nvi package allows local users to delete files via malformed entries in vi.recover."),
	(1516, "CVE-1999-0154", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 2.0 and 3.0 allows remote attackers to read the source code for ASP pages by appending a . (dot) to the end of the URL."),
	(1517, "CVE-1999-0808", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Multiple buffer overflows in ISC DHCP Distribution server (dhcpd) 1.0 and 2.0 allow a remote attacker to cause a denial of service (crash) and possibly execute arbitrary commands via long options."),
	(1518, "CVE-1999-0815", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Memory leak in SNMP agent in Windows NT 4.0 before SP5 allows remote attackers to conduct a denial of service (memory exhaustion) via a large number of queries."),
	(1519, "CVE-1999-1035", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 3.0 and 4.0 on x86 and Alpha allows remote attackers to cause a denial of service (hang) via a malformed GET request, aka the IIS \"GET\" vulnerability."),
	(1520, "CVE-1999-1042", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Cisco Resource Manager (CRM) 1.0 and 1.1 creates world-readable log files and temporary files, which may expose sensitive information, to local users such as user IDs, passwords and SNMP community strings."),
	(1521, "CVE-1999-1043", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Exchange Server 5.5 and 5.0 does not properly handle (1) malformed NNTP data, or (2) malformed SMTP data, which allows remote attackers to cause a denial of service (application error)."),
	(1522, "CVE-1999-1055", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Excel 97 does not warn the user before executing worksheet functions, which could allow attackers to execute arbitrary commands by using the CALL function to execute a malicious DLL, aka the Excel \"CALL Vulnerability.\""),
	(1523, "CVE-1999-1074", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Webmin before 0.5 does not restrict the number of invalid passwords that are entered for a valid username, which could allow remote attackers to gain privileges via brute force password cracking."),
	(1524, "CVE-1999-1084", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "The \"AEDebug\" registry key is installed with insecure permissions, which allows local users to modify the key to specify a Trojan Horse debugger which is automatically executed on a system crash."),
	(1525, "CVE-1999-1087", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4 treats a 32-bit number (\"dotless IP address\") in the a URL as the hostname instead of an IP address, which causes IE to apply Local Intranet Zone settings to the resulting web page, allowing remote malicious web servers to conduct unauthorized activities by using URLs that contain the dotless IP address for their server."),
	(1526, "CVE-1999-1093", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the Window.External function in the JScript Scripting Engine in Internet Explorer 4.01 SP1 and earlier allows remote attackers to execute arbitrary commands via a malicious web page."),
	(1527, "CVE-1999-1094", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Internet Explorer 4.01 and earlier allows remote attackers to execute arbitrary commands via a long URL with the \"mk:\" protocol, aka the \"MK Overrun security issue.\""),
	(1528, "CVE-1999-1100", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Cisco PIX Private Link 4.1.6 and earlier does not properly process certain commands in the configuration file, which reduces the effective key length of the DES key to 48 bits instead of 56 bits, which makes it easier for an attacker to find the proper key via a brute force attack."),
	(1529, "CVE-1999-1102", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "lpr on SunOS 4.1.1, BSD 4.3, A/UX 2.0.1, and other BSD-based operating systems allows local users to create or overwrite arbitrary files via a symlink attack that is triggered after invoking lpr 1000 times."),
	(1530, "CVE-1999-1104", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows 95 uses weak encryption for the password list (.pwl) file used when password caching is enabled, which allows local users to gain privileges by decrypting the passwords."),
	(1531, "CVE-1999-1105", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows 95, when Remote Administration and File Sharing for NetWare Networks is enabled, creates a share (C$) when an administrator logs in remotely, which allows remote attackers to read arbitrary files by mapping the network drive."),
	(1532, "CVE-1999-1117", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "lquerypv in AIX 4.1 and 4.2 allows local users to read arbitrary files by specifying the file in the -h command line parameter."),
	(1533, "CVE-1999-1124", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "HTTP Client application in ColdFusion allows remote attackers to bypass access restrictions for web pages on other ports by providing the target page to the mainframeset.cfm application, which requests the page from the server, making it look like the request is coming from the local host."),
	(1534, "CVE-1999-1126", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Cisco Resource Manager (CRM) 1.1 and earlier creates certain files with insecure permissions that allow local users to obtain sensitive configuration information including usernames, passwords, and SNMP community strings, from (1) swim_swd.log, (2) swim_debug.log, (3) dbi_debug.log, and (4) temporary files whose names begin with \"DPR_\"."),
	(1535, "CVE-1999-1127", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 does not properly shut down invalid named pipe RPC connections, which allows remote attackers to cause a denial of service (resource exhaustion) via a series of connections containing malformed data, aka the \"Named Pipes Over RPC\" vulnerability."),
	(1536, "CVE-1999-1132", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 allows remote attackers to cause a denial of service (crash) via extra source routing data such as (1) a Routing Information Field (RIF) field with a hop count greater than 7, or (2) a list containing duplicate Token Ring IDs."),
	(1537, "CVE-1999-1148", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "FTP service in IIS 4.0 and earlier allows remote attackers to cause a denial of service (resource exhaustion) via many passive (PASV) connections at the same time."),
	(1538, "CVE-1999-1157", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Tcpip.sys in Windows NT 4.0 before SP4 allows remote attackers to cause a denial of service via an ICMP Subnet Mask Address Request packet, when certain multiple IP addresses are bound to the same network interface."),
	(1539, "CVE-1999-1167", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Cross-site scripting vulnerability in Third Voice Web annotation utility allows remote users to read sensitive data and generate fake web pages for other Third Voice users by injecting malicious Javascript into an annotation."),
	(1540, "CVE-1999-1175", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Web Cache Control Protocol (WCCP) in Cisco Cache Engine for Cisco IOS 11.2 and earlier does not use authentication, which allows remote attackers to redirect HTTP traffic to arbitrary hosts via WCCP packets to UDP port 2048."),
	(1541, "CVE-1999-1177", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Directory traversal vulnerability in nph-publish before 1.2 allows remote attackers to overwrite arbitrary files via a .. (dot dot) in the pathname for an upload operation."),
	(1542, "CVE-1999-1206", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "SystemSoft SystemWizard package in HP Pavilion PC with Windows 98, and possibly other platforms and operating systems, installs two ActiveX controls that are marked as safe for scripting, which allows remote attackers to execute arbitrary commands via a malicious web page that references (1) the Launch control, or (2) the RegObj control."),
	(1543, "CVE-1999-1222", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Netbt.sys in Windows NT 4.0 allows remote malicious DNS servers to cause a denial of service (crash) by returning 0.0.0.0 as the IP address for a DNS host name lookup."),
	(1544, "CVE-1999-1223", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 3.0 allows remote attackers to cause a denial of service via a request to an ASP page in which the URL contains a large number of / (forward slash) characters."),
	(1545, "CVE-1999-1233", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 4.0 does not properly restrict access for the initial session request from a user\'s IP address if the address does not resolve to a DNS domain, aka the \"Domain Resolution\" vulnerability."),
	(1546, "CVE-1999-1246", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Direct Mailer feature in Microsoft Site Server 3.0 saves user domain names and passwords in plaintext in the TMLBQueue network share, which has insecure default permissions, allowing remote attackers to read the passwords and gain privileges."),
	(1547, "CVE-1999-1259", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Office 98, Macintosh Edition, does not properly initialize the disk space used by Office 98 files and effectively inserts data from previously deleted files into the Office file, which could allow attackers to obtain sensitive information."),
	(1548, "CVE-1999-1279", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "An interaction between the AS/400 shared folders feature and Microsoft SNA Server 3.0 and earlier allows users to view each other\'s folders when the users share the same Local APPC LU."),
	(1549, "CVE-1999-1287", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Analog 3.0 and earlier allows remote attackers to read arbitrary files via the forms interface."),
	(1550, "CVE-1999-1290", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in nftp FTP client version 1.40 allows remote malicious FTP servers to cause a denial of service, and possibly execute arbitrary commands, via a long response string."),
	(1551, "CVE-1999-1293", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "mod_proxy in Apache 1.2.5 and earlier allows remote attackers to cause a denial of service via malformed FTP commands, which causes Apache to dump core."),
	(1552, "CVE-1999-1294", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Office Shortcut Bar (OSB) in Windows 3.51 enables backup and restore permissions, which are inherited by programs such as File Manager that are started from the Shortcut Bar, which could allow local users to read folders for which they do not have permission."),
	(1553, "CVE-1999-1300", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in accton in Cray UNICOS 6.1 and 6.0 allows local users to read arbitrary files and modify system accounting configuration."),
	(1554, "CVE-1999-1307", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in urestore in Novell UnixWare 1.1 allows local users to gain root privileges."),
	(1555, "CVE-1999-1315", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerabilities in DECnet/OSI for OpenVMS before 5.8 on DEC Alpha AXP and VAX/VMS systems allow local users to gain privileges or cause a denial of service."),
	(1556, "CVE-1999-1316", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Passfilt.dll in Windows NT SP2 allows users to create a password that contains the user\'s name, which could make it easier for an attacker to guess."),
	(1557, "CVE-1999-1317", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 SP4 and earlier allows local users to gain privileges by modifying the symbolic link table in the \\?? object folder using a different case letter (upper or lower) to point to a different device."),
	(1558, "CVE-1999-1320", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Novell NetWare 3.x and earlier allows local users to gain privileges via packet spoofing."),
	(1559, "CVE-1999-1324", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "VAXstations running Open VMS 5.3 through 5.5-2 with VMS DECwindows or MOTIF do not properly disable access to user accounts that exceed the break-in limit threshold for failed login attempts, which makes it easier for attackers to conduct brute force password guessing."),
	(1560, "CVE-1999-1325", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "SAS System 5.18 on VAX/VMS is installed with insecure permissions for its directories and startup file, which allows local users to gain privileges."),
	(1561, "CVE-1999-1327", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in linuxconf 1.11r11-rh2 on Red Hat Linux 5.1 allows local users to gain root privileges via a long LANG environmental variable."),
	(1562, "CVE-1999-1328", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "linuxconf before 1.11.r11-rh3 on Red Hat Linux 5.1 allows local users to overwrite arbitrary files and gain root access via a symlink attack."),
	(1563, "CVE-1999-1329", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in SysVInit in Red Hat Linux 5.1 and earlier allows local users to gain privileges."),
	(1564, "CVE-1999-1330", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "The snprintf function in the db library 1.85.4 ignores the size parameter, which could allow attackers to exploit buffer overflows that would be prevented by a properly implemented snprintf."),
	(1565, "CVE-1999-1331", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "netcfg 2.16-1 in Red Hat Linux 4.2 allows the Ethernet interface to be controlled by users on reboot when an option is set, which allows local users to cause a denial of service by shutting down the interface."),
	(1566, "CVE-1999-1332", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "gzexe in the gzip package on Red Hat Linux 5.0 and earlier allows local users to overwrite files of other users via a symlink attack on a temporary file."),
	(1567, "CVE-1999-1333", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "automatic download option in ncftp 2.4.2 FTP client in Red Hat Linux 5.0 and earlier allows remote attackers to execute arbitrary commands via shell metacharacters in the names of files that are to be downloaded."),
	(1568, "CVE-1999-1334", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Multiple buffer overflows in filter command in Elm 2.4 allows attackers to execute arbitrary commands via (1) long From: headers, (2) long Reply-To: headers, or (3) via a long -f (filterfile) command line argument."),
	(1569, "CVE-1999-1335", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "snmpd server in cmu-snmp SNMP package before 3.3-1 in Red Hat Linux 4.0 is configured to allow remote attackers to read and write sensitive information."),
	(1570, "CVE-1999-1339", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability when Network Address Translation (NAT) is enabled in Linux 2.2.10 and earlier with ipchains, or FreeBSD 3.2 with ipfw, allows remote attackers to cause a denial of service (kernel panic) via a ping -R (record route) command."),
	(1571, "CVE-1999-1355", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "BMC Patrol component, when installed with Compaq Insight Management Agent 4.23 and earlier, or Management Agents for Servers 4.40 and earlier, creates a PFCUser account with a default password and potentially dangerous privileges."),
	(1572, "CVE-1999-1358", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "When an administrator in Windows NT or Windows 2000 changes a user policy, the policy is not properly updated if the local ntconfig.pol is not writable by the user, which could allow local users to bypass restrictions that would otherwise be enforced by the policy, possibly by changing the policy file to be read-only."),
	(1573, "CVE-1999-1359", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "When the Ntconfig.pol file is used on a server whose name is longer than 13 characters, Windows NT does not properly enforce policies for global groups, which could allow users to bypass restrictions that were intended by those policies."),
	(1574, "CVE-1999-1360", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 allows local users to cause a denial of service via a user mode application that closes a handle that was opened in kernel mode, which causes a crash when the kernel attempts to close the handle."),
	(1575, "CVE-1999-1362", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Win32k.sys in Windows NT 4.0 before SP2 allows local users to cause a denial of service (crash) by calling certain WIN32K functions with incorrect parameters."),
	(1576, "CVE-1999-1363", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 3.51 and 4.0 allow local users to cause a denial of service (crash) by running a program that creates a large number of locks on a file, which exhausts the NonPagedPool."),
	(1577, "CVE-1999-1364", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT 4.0 allows local users to cause a denial of service (crash) via an illegal kernel mode address to the functions (1) GetThreadContext or (2) SetThreadContext."),
	(1578, "CVE-1999-1379", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "DNS allows remote attackers to use DNS name servers as traffic amplifiers via a UDP DNS query with a spoofed source address, which produces more traffic to the victim than was sent by the attacker."),
	(1579, "CVE-1999-1382", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "NetWare NFS mode 1 and 2 implements the \"Read Only\" flag in Unix by changing the ownership of a file to root, which allows local users to gain root privileges by creating a setuid program and setting it to \"Read Only,\" which NetWare-NFS changes to a setuid root program."),
	(1580, "CVE-1999-1386", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Perl 5.004_04 and earlier follows symbolic links when running with the -e option, which allows local users to overwrite arbitrary files via a symlink attack on the /tmp/perl-eaXXXXX file."),
	(1581, "CVE-1999-1444", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "genkey utility in Alibaba 2.0 generates RSA key pairs with an exponent of 1, which results in transactions that are sent in cleartext."),
	(1582, "CVE-1999-1451", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "The Winmsdp.exe sample file in IIS 4.0 and Site Server 3.0 allows remote attackers to read arbitrary files."),
	(1583, "CVE-1999-1452", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "GINA in Windows NT 4.0 allows attackers with physical access to display a portion of the clipboard of the user who has locked the workstation by pasting (CTRL-V) the contents into the username prompt."),
	(1584, "CVE-1999-1455", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "RSH service utility RSHSVC in Windows NT 3.5 through 4.0 does not properly restrict access as specified in the .Rhosts file when a user comes from an authorized host, which could allow unauthorized users to access the service by logging in from an authorized host."),
	(1585, "CVE-1999-1456", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "thttpd HTTP server 2.03 and earlier allows remote attackers to read arbitrary files via a GET request with more than one leading / (slash) character in the filename."),
	(1586, "CVE-1999-1462", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in bb-hist.sh CGI History module in Big Brother 1.09b and 1.09c allows remote attackers to read portions of arbitrary files."),
	(1587, "CVE-1999-1464", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Cisco IOS 11.1CC and 11.1CT with distributed fast switching (DFS) enabled allows remote attackers to bypass certain access control lists when the router switches traffic from a DFS-enabled interface to an interface that does not have DFS enabled, as described by Cisco bug CSCdk35564."),
	(1588, "CVE-1999-1465", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in Cisco IOS 11.1 through 11.3 with distributed fast switching (DFS) enabled allows remote attackers to bypass certain access control lists when the router switches traffic from a DFS-enabled input interface to an output interface with a logical subinterface, as described by Cisco bug CSCdk43862."),
	(1589, "CVE-1999-1472", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.0 allows remote attackers to read arbitrary text and HTML files on the user\'s machine via a small IFRAME that uses Dynamic HTML (DHTML) to send the data to the attacker, aka the Freiburg text-viewing issue."),
	(1590, "CVE-1999-1473", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "When a Web site redirects the browser to another site, Internet Explorer 3.02 and 4.0 automatically resends authentication information to the second site, aka the \"Page Redirect Issue.\""),
	(1591, "CVE-1999-1474", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "PowerPoint 95 and 97 allows remote attackers to cause an application to be run automatically without prompting the user, possibly through the slide show, when the document is opened in browsers such as Internet Explorer."),
	(1592, "CVE-1999-1476", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "A bug in Intel Pentium processor (MMX and Overdrive) allows local users to cause a denial of service (hang) in Intel-based operating systems such as Windows NT and Windows 95, via an invalid instruction, aka the \"Invalid Operand with Locked CMPXCHG8B Instruction\" problem."),
	(1593, "CVE-1999-1481", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Squid 2.2.STABLE5 and below, when using external authentication, allows attackers to bypass access controls via a newline in the user/password pair."),
	(1594, "CVE-1999-1488", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "sdrd daemon in IBM SP2 System Data Repository (SDR) allows remote attackers to read files without authentication."),
	(1595, "CVE-1999-1512", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "The AMaViS virus scanner 0.2.0-pre4 and earlier allows remote attackers to execute arbitrary commands as root via an infected mail message with shell metacharacters in the reply-to field."),
	(1596, "CVE-1999-1584", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Unknown vulnerability in (1) loadmodule, and (2) modload if modload is installed with setuid/setgid privileges, in SunOS 4.1.1 through 4.1.3c, and Open Windows 3.0, allows local users to gain root privileges via environment variables, a different vulnerability than CVE-1999-1586."),
	(1597, "CVE-1999-1585", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "The (1) rcS and (2) mountall programs in Sun Solaris 2.x, possibly before 2.4, start a privileged shell on the system console if fsck fails while the system is booting, which allows attackers with physical access to gain root privileges."),
	(1598, "CVE-1999-1586", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "loadmodule in SunOS 4.1.x, as used by xnews, does not properly sanitize its environment, which allows local users to gain privileges, a different vulnerability than CVE-1999-1584."),
	(1599, "CVE-1999-1587", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "/usr/ucb/ps in Sun Microsystems Solaris 8 and 9, and certain earlier releases, allows local users to view the environment variables and values of arbitrary processes via the -e option."),
	(1600, "CVE-1999-1588", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in nlps_server in Sun Solaris x86 2.4, 2.5, and 2.5.1 allows remote attackers to execute arbitrary code as root via a long string beginning with \"NLPS:002:002:\" to the listen (aka System V listener) port, TCP port 2766."),
	(1601, "CVE-1999-1589", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Unspecified vulnerability in crontab in IBM AIX 3.2 allows local users to gain root privileges via unknown attack vectors."),
