	(1605, "CVE-2000-0011", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in AnalogX SimpleServer:WWW HTTP server allows remote attackers to execute commands via a long GET request."),
	(1606, "CVE-2000-0013", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "IRIX soundplayer program allows local users to gain privileges by including shell metacharacters in a .wav file, which is executed via the midikeys program."),
	(1607, "CVE-2000-0015", "1999-12-31T05:00:00.000", "2025-04-03T01:03:51.193", "CascadeView TFTP server allows local users to gain privileges via a symlink attack."),
