	(1611, "CVE-2000-0077", "2000-01-02T05:00:00.000", "2025-04-03T01:03:51.193", "The October 1998 version of the HP-UX aserver program allows local users to gain privileges by specifying an alternate PATH which aserver uses to find the ps and grep commands."),
	(1612, "CVE-2000-0078", "2000-01-02T05:00:00.000", "2025-04-03T01:03:51.193", "The June 1999 version of the HP-UX aserver program allows local users to gain privileges by specifying an alternate PATH which aserver uses to find the awk command."),
