	(1615, "CVE-1999-0744", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Netscape Enterprise Server and FastTrask Server allows remote attackers to gain privileges via a long HTTP GET request."),
	(1616, "CVE-1999-0876", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Internet Explorer 4.0 via EMBED tag."),
	(1617, "CVE-1999-0894", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "Red Hat Linux screen program does not use Unix98 ptys, allowing local users to write to other terminals."),
	(1618, "CVE-2000-0049", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Winamp client allows remote attackers to execute commands via a long entry in a .pls file."),
	(1619, "CVE-2000-0050", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "The Allaire Spectra Webtop allows authenticated users to access other Webtop sections by specifying explicit URLs."),
	(1620, "CVE-2000-0051", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "The Allaire Spectra Configuration Wizard allows remote attackers to cause a denial of service by repeatedly resubmitting data collections for indexing via a URL."),
	(1621, "CVE-2000-0052", "2000-01-04T05:00:00.000", "2025-04-03T01:03:51.193", "Red Hat userhelper program in the usermode package allows local users to gain root access via PAM and a .. (dot dot) attack."),
