	(1637, "CVE-2000-0081", "2000-01-10T05:00:00.000", "2025-04-03T01:03:51.193", "Hotmail does not properly filter JavaScript code from a user\'s mailbox, which allows a remote attacker to execute the code by using hexadecimal codes to specify the javascript: protocol, e.g. j&#x41;vascript."),
	(1638, "CVE-2000-0045", "2000-01-11T05:00:00.000", "2025-04-03T01:03:51.193", "MySQL allows local users to modify passwords for arbitrary MySQL users via the GRANT privilege."),
	(1639, "CVE-2000-0067", "2000-01-11T05:00:00.000", "2025-04-03T01:03:51.193", "CyberCash Merchant Connection Kit (MCK) allows local users to modify files via a symlink attack."),
	(1640, "CVE-2000-0071", "2000-01-11T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 4.0 allows a remote attacker to obtain the real pathname of the document root by requesting non-existent files with .ida or .idq extensions."),
	(1641, "CVE-2000-0074", "2000-01-11T05:00:00.000", "2025-04-03T01:03:51.193", "PowerScripts PlusMail CGI program allows remote attackers to execute commands via a password file with improper permissions."),
