	(1648, "CVE-2000-0063", "2000-01-17T05:00:00.000", "2025-04-03T01:03:51.193", "cgiproc CGI script in Nortel Contivity HTTP server allows remote attackers to read arbitrary files by specifying the filename in a parameter to the script."),
