	(1678, "CVE-2000-0103", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The SmartCart shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1679, "CVE-2000-0104", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The Shoptron shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1680, "CVE-2000-0105", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "Outlook Express 5.01 and Internet Explorer 5.01 allow remote attackers to view a user\'s email messages via a script that accesses a variable that references subsequent email messages that are read by the client."),
	(1681, "CVE-2000-0106", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The EasyCart shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1682, "CVE-2000-0107", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "Linux apcd program allows local attackers to modify arbitrary files via a symlink attack."),
	(1683, "CVE-2000-0108", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The Intellivend shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1684, "CVE-2000-0110", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The WebSiteTool shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
