	(1688, "CVE-2000-0133", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflows in Tiny FTPd 0.52 beta3 FTP server allows users to execute commands via the STOR, RNTO, MKD, XMKD, RMD, XRMD, APPE, SIZE, and RNFR commands."),
	(1689, "CVE-2000-0134", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The Check It Out shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1690, "CVE-2000-0135", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The @Retail shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
	(1691, "CVE-2000-0136", "2000-02-01T05:00:00.000", "2025-04-03T01:03:51.193", "The Cart32 shopping cart application allows remote users to modify sensitive purchase information via hidden form fields."),
