	(1696, "CVE-2000-0112", "2000-02-02T05:00:00.000", "2025-04-03T01:03:51.193", "The default installation of Debian GNU/Linux uses an insecure Master Boot Record (MBR) which allows a local user to boot from a floppy disk during the installation."),
	(1697, "CVE-2000-0114", "2000-02-02T05:00:00.000", "2025-04-03T01:03:51.193", "Frontpage Server Extensions allows remote attackers to determine the name of the anonymous account via an RPC POST request to shtml.dll in the /_vti_bin/ virtual directory."),
	(1698, "CVE-2000-0469", "2000-02-02T05:00:00.000", "2025-04-03T01:03:51.193", "Selena Sol WebBanner 4.0 allows remote attackers to read arbitrary files via a .. (dot dot) attack."),
	(1699, "CVE-2000-0122", "2000-02-03T05:00:00.000", "2025-04-03T01:03:51.193", "Frontpage Server Extensions allows remote attackers to determine the physical path of a virtual directory via a GET request to the htimage.exe CGI program."),
	(1700, "CVE-2000-0124", "2000-02-03T05:00:00.000", "2025-04-03T01:03:51.193", "surfCONTROL SuperScout does not properly asign a category to web sites with a . (dot) at the end, which may allow users to bypass web access restrictions."),
	(1701, "CVE-2000-0125", "2000-02-03T05:00:00.000", "2025-04-03T01:03:51.193", "wwwthreads does not properly cleanse numeric data or table names that are passed to SQL queries, which allows remote attackers to gain privileges for wwwthreads forums."),
	(1702, "CVE-2000-0127", "2000-02-03T05:00:00.000", "2025-04-03T01:03:51.193", "The Webspeed configuration program does not properly disable access to the WSMadmin utility, which allows remote attackers to gain privileges via wsisa.dll."),
	(1703, "CVE-2000-0218", "2000-02-03T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Linux mount and umount allows local users to gain root privileges via a long relative pathname."),
	(1704, "CVE-2000-0089", "2000-02-04T05:00:00.000", "2025-04-03T01:03:51.193", "The rdisk utility in Microsoft Terminal Server Edition and Windows NT 4.0 stores registry hive information in a temporary file with permissions that allow local users to read it, aka the \"RDISK Registry Enumeration File\" vulnerability."),
	(1705, "CVE-2000-0128", "2000-02-04T05:00:00.000", "2025-04-03T01:03:51.193", "The Finger Server 0.82 allows remote attackers to execute commands via shell metacharacters."),
	(1706, "CVE-2000-0129", "2000-02-04T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the SHGetPathFromIDList function of the Serv-U FTP server allows attackers to cause a denial of service by performing a LIST command on a malformed .lnk file."),
	(1707, "CVE-2000-0145", "2000-02-05T05:00:00.000", "2025-04-03T01:03:51.193", "The libguile.so library file used by gnucash in Debian GNU/Linux is installed with world-writable permissions."),
	(1708, "CVE-2000-0472", "2000-02-06T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in innd 2.2.2 allows remote attackers to execute arbitrary commands via a cancel request containing a long message ID."),
	(1709, "CVE-2000-0144", "2000-02-07T05:00:00.000", "2025-04-03T01:03:51.193", "Axis 700 Network Scanner does not properly restrict access to administrator URLs, which allows users to bypass the password protection via a .. (dot dot) attack."),
	(1710, "CVE-2000-0146", "2000-02-07T05:00:00.000", "2025-04-03T01:03:51.193", "The Java Server in the Novell GroupWise Web Access Enhancement Pack allows remote attackers to cause a denial of service via a long URL to the servlet."),
	(1711, "CVE-2000-0147", "2000-02-08T05:00:00.000", "2025-04-03T01:03:51.193", "snmpd in SCO OpenServer has an SNMP community string that is writable by default, which allows local attackers to modify the host\'s configuration."),
	(1712, "CVE-2000-0148", "2000-02-08T05:00:00.000", "2025-04-03T01:03:51.193", "MySQL 3.22 allows remote attackers to bypass password authentication and access a database via a short check string."),
	(1713, "CVE-2000-0149", "2000-02-08T05:00:00.000", "2025-04-03T01:03:51.193", "Zeus web server allows remote attackers to view the source code for CGI programs via a null character (%00) at the end of a URL."),
	(1714, "CVE-2000-0215", "2000-02-08T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in SCO cu program in UnixWare 7.x allows local users to gain privileges."),
	(1715, "CVE-2000-0140", "2000-02-10T05:00:00.000", "2025-04-03T01:03:51.193", "Internet Anywhere POP3 Mail Server allows remote attackers to cause a denial of service via a large number of connections."),
	(1716, "CVE-2000-0141", "2000-02-11T05:00:00.000", "2025-04-03T01:03:51.193", "Infopop Ultimate Bulletin Board (UBB) allows remote attackers to execute commands via shell metacharacters in the topic hidden field."),
	(1717, "CVE-2000-0142", "2000-02-11T05:00:00.000", "2025-04-03T01:03:51.193", "The authentication protocol in Timbuktu Pro 2.0b650 allows remote attackers to cause a denial of service via connections to port 407 and 1417."),
	(1718, "CVE-2000-0143", "2000-02-11T05:00:00.000", "2025-04-03T01:03:51.193", "The SSH protocol server sshd allows local users without shell access to redirect a TCP connection through a service that uses the standard system password database for authentication, such as POP or FTP."),
	(1719, "CVE-2000-0150", "2000-02-12T05:00:00.000", "2025-04-03T01:03:51.193", "Check Point Firewall-1 allows remote attackers to bypass port access restrictions on an FTP server by forcing it to send malicious packets that Firewall-1 misinterprets as a valid 227 response to a client\'s PASV attempt."),
	(1720, "CVE-2000-0197", "2000-02-14T05:00:00.000", "2025-04-03T01:03:51.193", "The Windows NT scheduler uses the drive mapping of the interactive user who is currently logged onto the system, which allows the local user to gain privileges by providing a Trojan horse batch file in place of the original batch file."),
	(1721, "CVE-2000-0167", "2000-02-15T05:00:00.000", "2025-04-03T01:03:51.193", "IIS Inetinfo.exe allows local users to cause a denial of service by creating a mail file with a long name and a .txt.eml extension in the pickup directory."),
	(1722, "CVE-2000-0222", "2000-02-15T05:00:00.000", "2025-04-03T01:03:51.193", "The installation for Windows 2000 does not activate the Administrator password until the system has rebooted, which allows remote attackers to connect to the ADMIN$ share without a password until the reboot occurs."),
	(1723, "CVE-2000-0224", "2000-02-15T05:00:00.000", "2025-04-03T01:03:51.193", "ARCserve agent in SCO UnixWare 7.x allows local attackers to gain root privileges via a symlink attack."),
	(1724, "CVE-2000-0094", "2000-02-16T05:00:00.000", "2025-04-03T01:03:51.193", "procfs in BSD systems allows local users to gain root privileges by modifying the /proc/pid/mem interface via a modified file descriptor for stderr."),
	(1725, "CVE-2000-0154", "2000-02-16T05:00:00.000", "2025-04-03T01:03:51.193", "The ARCserve agent in UnixWare allows local attackers to modify arbitrary files via a symlink attack."),
	(1726, "CVE-2000-0156", "2000-02-16T05:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.x and 5.x allows remote web servers to access files on the client that are outside of its security domain, aka the \"Image Source Redirect\" vulnerability."),
	(1727, "CVE-2000-0158", "2000-02-16T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in MMDF server allows remote attackers to gain privileges via a long MAIL FROM command to the SMTP daemon."),
	(1728, "CVE-2000-0159", "2000-02-17T05:00:00.000", "2025-04-03T01:03:51.193", "HP Ignite-UX does not save /etc/passwd when it creates an image of a trusted system, which can set the password field to a blank and allow an attacker to gain privileges."),
	(1729, "CVE-2000-0155", "2000-02-18T05:00:00.000", "2025-04-03T01:03:51.193", "Windows NT Autorun executes the autorun.inf file on non-removable media, which allows local attackers to specify an alternate program to execute when other users access a drive."),
	(1730, "CVE-2000-0161", "2000-02-18T05:00:00.000", "2025-04-03T01:03:51.193", "Sample web sites on Microsoft Site Server 3.0 Commerce Edition do not validate an identification number, which allows remote attackers to execute SQL commands."),
	(1731, "CVE-2000-0162", "2000-02-18T05:00:00.000", "2025-04-03T01:03:51.193", "The Microsoft virtual machine (VM) in Internet Explorer 4.x and 5.x allows a remote attacker to read files via a malicious Java applet that escapes the Java sandbox, aka the \"VM File Reading\" vulnerability."),
	(1732, "CVE-2000-0164", "2000-02-20T05:00:00.000", "2025-04-03T01:03:51.193", "The installation of Sun Internet Mail Server (SIMS) creates a world-readable file that allows local users to obtain passwords."),
	(1733, "CVE-2000-0160", "2000-02-21T05:00:00.000", "2025-04-03T01:03:51.193", "The Microsoft Active Setup ActiveX component in Internet Explorer 4.x and 5.x allows a remote attacker to install software components without prompting the user by stating that the software\'s manufacturer is Microsoft."),
	(1734, "CVE-2000-0163", "2000-02-21T05:00:00.000", "2025-04-03T01:03:51.193", "asmon and ascpu in FreeBSD allow local users to gain root privileges via a configuration file."),
	(1735, "CVE-2000-0166", "2000-02-21T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the InterAccess telnet server TelnetD allows remote attackers to execute commands via a long login name."),
	(1736, "CVE-2000-0210", "2000-02-21T05:00:00.000", "2025-04-03T01:03:51.193", "The lit program in Sun Flex License Manager (FlexLM) follows symlinks, which allows local users to modify arbitrary files."),
	(1737, "CVE-2000-0182", "2000-02-23T05:00:00.000", "2025-04-03T01:03:51.193", "iPlanet Web Server 4.1 allows remote attackers to cause a denial of service via a large number of GET commands, which consumes memory and causes a kernel panic."),
	(1738, "CVE-2000-0211", "2000-02-23T05:00:00.000", "2025-04-03T01:03:51.193", "The Windows Media server allows remote attackers to cause a denial of service via a series of client handshake packets that are sent in an improper sequence, aka the \"Misordered Windows Media Services Handshake\" vulnerability."),
	(1739, "CVE-2000-0213", "2000-02-23T05:00:00.000", "2025-04-03T01:03:51.193", "The Sambar server includes batch files ECHO.BAT and HELLO.BAT in the CGI directory, which allow remote attackers to execute commands via shell metacharacters."),
	(1740, "CVE-2000-0219", "2000-02-23T05:00:00.000", "2025-04-03T01:03:51.193", "Red Hat 6.0 allows local users to gain root access by booting single user and hitting ^C at the password prompt."),
	(1741, "CVE-2000-0194", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "buildxconf in Corel Linux allows local users to modify or create arbitrary files via the -x or -f parameters."),
	(1742, "CVE-2000-0195", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "setxconf in Corel Linux allows local users to gain root access via the -T parameter, which executes the user\'s .xserverrc file."),
	(1743, "CVE-2000-0212", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "InterAccess TelnetD Server 4.0 allows remote attackers to conduct a denial of service via malformed terminal client configuration information."),
	(1744, "CVE-2000-0214", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "FTP Explorer uses weak encryption for storing the username, password, and profile of FTP sites."),
	(1745, "CVE-2000-0217", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of SSH allows X forwarding, which could allow a remote attacker to control a client\'s X sessions via a malicious xauth program."),
	(1746, "CVE-2000-0220", "2000-02-24T05:00:00.000", "2025-04-03T01:03:51.193", "ZoneAlarm sends sensitive system and network information in cleartext to the Zone Labs server if a user requests more information about an event."),
	(1747, "CVE-2000-0221", "2000-02-25T05:00:00.000", "2025-04-03T01:03:51.193", "The Nautica Marlin bridge allows remote attackers to cause a denial of service via a zero length UDP packet to the SNMP port."),
	(1748, "CVE-2000-0170", "2000-02-26T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the man program in Linux allows local users to gain privileges via the MANPAGER environmental variable."),
	(1749, "CVE-2000-0187", "2000-02-27T05:00:00.000", "2025-04-03T01:03:51.193", "EZShopper 3.0 loadpage.cgi CGI script allows remote attackers to read arbitrary files via a .. (dot dot) attack or execute commands via shell metacharacters."),
	(1750, "CVE-2000-0188", "2000-02-27T05:00:00.000", "2025-04-03T01:03:51.193", "EZShopper 3.0 search.cgi CGI script allows remote attackers to read arbitrary files via a .. (dot dot) attack or execute commands via shell metacharacters."),
	(1751, "CVE-2000-0209", "2000-02-27T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Lynx 2.x allows remote attackers to crash Lynx and possibly execute commands via a long URL in a malicious web page."),
	(1752, "CVE-2000-0178", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "ServerIron switches by Foundry Networks have predictable TCP/IP sequence numbers, which allows remote attackers to spoof or hijack sessions."),
	(1753, "CVE-2000-0179", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "HP OpenView OmniBack 2.55 allows remote attackers to cause a denial of service via a large number of connections to port 5555."),
	(1754, "CVE-2000-0186", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the dump utility in the Linux ext2fs backup package allows local users to gain privileges via a long command line argument."),
	(1755, "CVE-2000-0196", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in mhshow in the Linux nmh package allows remote attackers to execute commands via malformed MIME headers in an email message."),
	(1756, "CVE-2000-0203", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "The Trend Micro OfficeScan client tmlisten.exe allows remote attackers to cause a denial of service via malformed data to port 12345."),
	(1757, "CVE-2000-0204", "2000-02-28T05:00:00.000", "2025-04-03T01:03:51.193", "The Trend Micro OfficeScan client allows remote attackers to cause a denial of service by making 5 connections to port 12345, which raises CPU utilization to 100%."),
	(1758, "CVE-2000-0176", "2000-02-29T05:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of Serv-U 2.5d and earlier allows remote attackers to determine the real pathname of the server by requesting a URL for a directory or file that does not exist."),
	(1759, "CVE-2000-0191", "2000-02-29T05:00:00.000", "2025-04-03T01:03:51.193", "Axis StorPoint CD allows remote attackers to access administrator URLs without authentication via a .. (dot dot) attack."),
	(1760, "CVE-2000-0208", "2000-02-29T05:00:00.000", "2025-04-03T01:03:51.193", "The htdig (ht://Dig) CGI program htsearch allows remote attackers to read arbitrary files by enclosing the file name with backticks (`) in parameters to htsearch."),
	(1761, "CVE-2000-0216", "2000-02-29T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft email clients in Outlook, Exchange, and Windows Messaging automatically respond to Read Receipt and Delivery Receipt tags, which could allow an attacker to flood a mail system with responses by forging a Read Receipt request that is redirected to a large distribution list."),
	(1762, "CVE-2000-0189", "2000-03-01T05:00:00.000", "2025-04-03T01:03:51.193", "ColdFusion Server 4.x allows remote attackers to determine the real pathname of the server via an HTTP request to the application.cfm or onrequestend.cfm files."),
	(1763, "CVE-2000-0201", "2000-03-01T05:00:00.000", "2025-04-03T01:03:51.193", "The window.showHelp() method in Internet Explorer 5.x does not restrict HTML help files (.chm) to be executed from the local host, which allows remote attackers to execute arbitrary commands via Microsoft Networking."),
	(1764, "CVE-2000-0207", "2000-03-01T05:00:00.000", "2025-04-03T01:03:51.193", "SGI InfoSearch CGI program infosrch.cgi allows remote attackers to execute commands via shell metacharacters."),
	(1765, "CVE-1999-0693", "2000-03-02T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in TT_SESSION environment variable in ToolTalk shared library allows local users to gain root privileges."),
	(1766, "CVE-2000-0177", "2000-03-02T05:00:00.000", "2025-04-03T01:03:51.193", "DNSTools CGI applications allow remote attackers to execute arbitrary commands via shell metacharacters."),
	(1767, "CVE-2000-0190", "2000-03-02T05:00:00.000", "2025-04-03T01:03:51.193", "AOL Instant Messenger (AIM) client allows remote attackers to cause a denial of service via a message with a malformed ASCII value."),
	(1768, "CVE-2000-0193", "2000-03-02T05:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of Dosemu in Corel Linux 1.0 allows local users to execute the system.com program and gain privileges."),
	(1769, "CVE-2000-0172", "2000-03-03T05:00:00.000", "2025-04-03T01:03:51.193", "The mtr program only uses a seteuid call when attempting to drop privileges, which could allow local users to gain root privileges."),
	(1770, "CVE-2000-0205", "2000-03-03T05:00:00.000", "2025-04-03T01:03:51.193", "Trend Micro OfficeScan allows remote attackers to replay administrative commands and modify the configuration of OfficeScan clients."),
	(1771, "CVE-2000-0168", "2000-03-04T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Windows 9x operating systems allow an attacker to cause a denial of service via a pathname that includes file device names, aka the \"DOS Device in Path Name\" vulnerability."),
	(1772, "CVE-2000-0192", "2000-03-05T05:00:00.000", "2025-04-03T01:03:51.193", "The default installation of Caldera OpenLinux 2.3 includes the CGI program rpm_query, which allows remote attackers to determine what packages are installed on the system."),
	(1773, "CVE-2000-0206", "2000-03-05T05:00:00.000", "2025-04-03T01:03:51.193", "The installation of Oracle 8.1.5.x on Linux follows symlinks and creates the orainstRoot.sh file with world-writeable permissions, which allows local users to gain privileges."),
	(1774, "CVE-2000-0200", "2000-03-06T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Microsoft Clip Art Gallery allows remote attackers to cause a denial of service or execute commands via a malformed CIL (clip art library) file, aka the \"Clip Art Buffer Overrun\" vulnerability."),
	(1775, "CVE-2000-0225", "2000-03-07T05:00:00.000", "2025-04-03T01:03:51.193", "The Pocsag POC32 program does not properly prevent remote users from accessing its server port, even if the option has been disabled."),
	(1776, "CVE-2000-0185", "2000-03-08T05:00:00.000", "2025-04-03T01:03:51.193", "RealMedia RealServer reveals the real IP address of a Real Server, even if the address is supposed to be private."),
	(1777, "CVE-2000-0202", "2000-03-08T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft SQL Server 7.0 and Microsoft Data Engine (MSDE) 1.0 allow remote attackers to gain privileges via a malformed Select statement in an SQL query."),
	(1778, "CVE-2000-0174", "2000-03-09T05:00:00.000", "2025-04-03T01:03:51.193", "StarOffice StarScheduler web server allows remote attackers to read arbitrary files via a .. (dot dot) attack."),
	(1779, "CVE-2000-0175", "2000-03-09T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in StarOffice StarScheduler web server allows remote attackers to gain root access via a long GET command."),
	(1780, "CVE-2000-0184", "2000-03-09T05:00:00.000", "2025-04-03T01:03:51.193", "Linux printtool sets the permissions of printer configuration files to be world-readable, which allows local attackers to obtain printer share passwords."),
	(1781, "CVE-2000-0173", "2000-03-10T05:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in the EELS system in SCO UnixWare 7.1.x allows remote attackers to cause a denial of service."),
	(1782, "CVE-2000-0183", "2000-03-10T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ircII 4.4 IRC client allows remote attackers to execute commands via the DCC chat capability."),
	(1783, "CVE-2000-0223", "2000-03-10T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the wmcdplay CD player program for the WindowMaker desktop allows local users to gain root privileges via a long parameter."),
	(1784, "CVE-2000-0171", "2000-03-11T05:00:00.000", "2025-04-03T01:03:51.193", "atsadc in the atsar package for Linux does not properly check the permissions of an output file, which allows local users to gain root privileges."),
	(1785, "CVE-2000-0181", "2000-03-11T05:00:00.000", "2025-04-03T01:03:51.193", "Firewall-1 3.0 and 4.0 leaks packets with private IP address information, which could allow remote attackers to determine the real IP address of the host that is making the connection."),
	(1786, "CVE-2000-0237", "2000-03-11T05:00:00.000", "2025-04-03T01:03:51.193", "Netscape Enterprise Server with Web Publishing enabled allows remote attackers to list arbitrary directories via a GET request for the /publisher directory, which provides a Java applet that allows the attacker to browse the directories."),
	(1787, "CVE-2000-0230", "2000-03-13T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in imwheel allows local users to gain root privileges via the imwheel-solo script and a long HOME environmental variable."),
	(1788, "CVE-2000-0180", "2000-03-14T05:00:00.000", "2025-04-03T01:03:51.193", "Sojourn search engine allows remote attackers to read arbitrary files via a .. (dot dot) attack."),
	(1789, "CVE-2000-0199", "2000-03-14T05:00:00.000", "2025-04-03T01:03:51.193", "When a new SQL Server is registered in Enterprise Manager for Microsoft SQL Server 7.0 and the \"Always prompt for login name and password\" option is not set, then the Enterprise Manager uses weak encryption to store the login ID and password."),
	(1790, "CVE-2000-0169", "2000-03-15T05:00:00.000", "2025-04-03T01:03:51.193", "Batch files in the Oracle web listener ows-bin directory allow remote attackers to execute commands via a malformed URL that includes \'?&\'."),
	(1791, "CVE-2000-0198", "2000-03-15T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in POP3 and IMAP servers in the MERCUR mail server suite allows remote attackers to cause a denial of service."),
	(1792, "CVE-2000-0233", "2000-03-15T05:00:00.000", "2025-04-03T01:03:51.193", "SuSE Linux IMAP server allows remote attackers to bypass IMAP authentication and gain privileges."),
	(1793, "CVE-2000-0239", "2000-03-15T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the MERCUR WebView WebMail server allows remote attackers to cause a denial of service via a long mail_user parameter in the GET request."),
	(1794, "CVE-2000-0231", "2000-03-16T05:00:00.000", "2025-04-03T01:03:51.193", "Linux kreatecd trusts a user-supplied path that is used to find the cdrecord program, allowing local users to gain root privileges."),
	(1795, "CVE-2000-0228", "2000-03-17T05:00:00.000", "2025-04-03T01:03:51.193", "Microsoft Windows Media License Manager allows remote attackers to cause a denial of service by sending a malformed request that causes the manager to halt, aka the \"Malformed Media License Request\" Vulnerability."),
	(1796, "CVE-2000-0236", "2000-03-17T05:00:00.000", "2025-04-03T01:03:51.193", "Netscape Enterprise Server with Directory Indexing enabled allows remote attackers to list server directories via web publishing tags such as ?wp-ver-info and ?wp-cs-dump."),
	(1797, "CVE-2000-0238", "2000-03-17T05:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the web server for Norton AntiVirus for Internet Email Gateways allows remote attackers to cause a denial of service via a long URL."),
	(1798, "CVE-2000-0226", "2000-03-20T05:00:00.000", "2025-04-03T01:03:51.193", "IIS 4.0 allows attackers to cause a denial of service by requesting a large buffer in a POST or PUT command which consumes memory, aka the \"Chunked Transfer Encoding Buffer Overflow Vulnerability.\""),
	(1799, "CVE-2000-0613", "2000-03-20T05:00:00.000", "2025-04-03T01:03:51.193", "Cisco Secure PIX Firewall does not properly identify forged TCP Reset (RST) packets, which allows remote attackers to force the firewall to close legitimate connections."),
	(1800, "CVE-2000-0240", "2000-03-21T05:00:00.000", "2025-04-03T01:03:51.193", "vqSoft vqServer program allows remote attackers to read arbitrary files via a /........../ in the URL, a variation of a .. (dot dot) attack."),
	(1801, "CVE-2000-0241", "2000-03-21T05:00:00.000", "2025-04-03T01:03:51.193", "vqSoft vqServer stores sensitive information such as passwords in cleartext in the server.cfg file, which allows attackers to gain privileges."),
	(1802, "CVE-2000-0229", "2000-03-22T05:00:00.000", "2025-04-03T01:03:51.193", "gpm-root in the gpm package does not properly drop privileges, which allows local users to gain privileges by starting a utility from gpm-root."),
