	(1821, "CVE-2000-0280", "2000-04-03T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the RealNetworks RealPlayer client versions 6 and 7 allows remote attackers to cause a denial of service via a long Location URL."),
	(1822, "CVE-2000-0297", "2000-04-03T04:00:00.000", "2025-04-03T01:03:51.193", "Allaire Forums 2.0.5 allows remote attackers to bypass access restrictions to secure conferences via the rightAccessAllForums or rightModerateAllForums variables."),
