	(1826, "CVE-2000-0251", "2000-04-06T04:00:00.000", "2025-04-03T01:03:51.193", "HP-UX 11.04 VirtualVault (VVOS) sends data to unprivileged processes via an interface that has multiple aliased IP addresses."),
	(1827, "CVE-2000-0300", "2000-04-06T04:00:00.000", "2025-04-03T01:03:51.193", "The default encryption method of PcAnywhere 9.x uses weak encryption, which allows remote attackers to sniff and decrypt PcAnywhere or NT domain accounts."),
	(1828, "CVE-2000-0301", "2000-04-06T04:00:00.000", "2025-04-03T01:03:51.193", "Ipswitch IMAIL server 6.02 and earlier allows remote attackers to cause a denial of service via the AUTH CRAM-MD5 command."),
