	(1833, "CVE-2000-0275", "2000-04-10T04:00:00.000", "2025-04-03T01:03:51.193", "CRYPTOCard CryptoAdmin for PalmOS uses weak encryption to store a user\'s PIN number, which allows an attacker with access to the .PDB file to generate valid PT-1 tokens after cracking the PIN."),
	(1834, "CVE-2000-0276", "2000-04-10T04:00:00.000", "2025-04-03T01:03:51.193", "BeOS 4.5 and 5.0 allow local users to cause a denial of service via malformed direct system calls using interrupt 37."),
