	(1898, "CVE-1999-0427", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "Eudora 4.1 allows remote attackers to perform a denial of service by sending attachments with long file names."),
	(1899, "CVE-2000-0341", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "ATRIUM Cassandra NNTP Server 1.10 allows remote attackers to cause a denial of service via a long login name."),
	(1900, "CVE-2000-0344", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "The knfsd NFS server in Linux kernel 2.2.x allows remote attackers to cause a denial of service via a negative size value."),
	(1901, "CVE-2000-0401", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflows in redirect.exe and changepw.exe in PDGSoft shopping cart allow remote attackers to execute arbitrary commands via a long query string."),
	(1902, "CVE-2000-0440", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "NetBSD 1.4.2 and earlier allows remote attackers to cause a denial of service by sending a packet with an unaligned IP timestamp option."),
	(1903, "CVE-2000-0447", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in WebShield SMTP 4.5.44 allows remote attackers to execute arbitrary commands via a long configuration parameter to the WebShield remote management service."),
	(1904, "CVE-2000-0448", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "The WebShield SMTP Management Tool version 4.5.44 does not properly restrict access to the management port when an IP address does not resolve to a hostname, which allows remote attackers to access the configuration via the GET_CONFIG command."),
	(1905, "CVE-2000-0449", "2000-05-01T04:00:00.000", "2025-04-03T01:03:51.193", "Omnis Studio 2.4 uses weak encryption (trivial encoding) for encrypting database fields."),
	(1906, "CVE-2000-0138", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "A system has a distributed denial of service (DDOS) attack master, agent, or zombie installed, such as (1) Trinoo, (2) Tribe Flood Network (TFN), (3) Tribe Flood Network 2000 (TFN2K), (4) stacheldraht, (5) mstream, or (6) shaft."),
	(1907, "CVE-2000-0293", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "aaa_base in SuSE Linux 6.3, and cron.daily in earlier versions, allow local users to delete arbitrary files by creating files whose names include spaces, which are then incorrectly interpreted by aaa_base when it deletes expired files from the /tmp directory."),
	(1908, "CVE-2000-0343", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Sniffit 0.3.x with the -L logging option enabled allows remote attackers to execute arbitrary commands via a long MAIL FROM mail header."),
	(1909, "CVE-2000-0346", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "AppleShare IP 6.1 and later allows a remote attacker to read potentially sensitive information via an invalid range request to the web server."),
	(1910, "CVE-2000-0347", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "Windows 95 and Windows 98 allow a remote attacker to cause a denial of service via a NetBIOS session request packet with a NULL source name."),
	(1911, "CVE-2000-0385", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "FileMaker Pro 5 Web Companion allows remote attackers to bypass Field-Level database security restrictions via the XML publishing or email capabilities."),
	(1912, "CVE-2000-0386", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "FileMaker Pro 5 Web Companion allows remote attackers to send anonymous or forged email."),
	(1913, "CVE-2000-0433", "2000-05-02T04:00:00.000", "2025-04-03T01:03:51.193", "The SuSE aaa_base package installs some system accounts with home directories set to /tmp, which allows local users to gain privileges to those accounts by creating standard user startup scripts such as profiles."),
	(1914, "CVE-2000-0303", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "Quake3 Arena allows malicious server operators to read or modify files on a client via a dot dot (..) attack."),
	(1915, "CVE-2000-0332", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "UltraBoard.pl or UltraBoard.cgi CGI scripts in UltraBoard 1.6 allows remote attackers to read arbitrary files via a pathname string that includes a dot dot (..) and ends with a null byte."),
	(1916, "CVE-2000-0335", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "The resolver in glibc 2.1.3 uses predictable IDs, which allows a local attacker to spoof DNS query results."),
	(1917, "CVE-2000-0345", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "The on-line help system options in Cisco routers allows non-privileged users without \"enabled\" access to obtain sensitive information via the show command."),
	(1918, "CVE-2000-0378", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "The pam_console PAM module in Linux systems performs a chown on various devices upon a user login, but an open file descriptor for those devices can be maintained after the user logs out, which allows that user to sniff activity on these devices when subsequent users log in."),
	(1919, "CVE-2000-0425", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the Web Archives component of L-Soft LISTSERV 1.8 allows remote attackers to execute arbitrary commands."),
	(1920, "CVE-2000-0430", "2000-05-03T04:00:00.000", "2025-04-03T01:03:51.193", "Cart32 allows remote attackers to access sensitive debugging information by appending /expdate to the URL request."),
	(1921, "CVE-2000-0414", "2000-05-04T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in shutdown command for HP-UX 11.X and 10.X allows allows local users to gain privileges via malformed input variables."),
	(1922, "CVE-2000-0422", "2000-05-04T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Netwin DMailWeb CGI program allows remote attackers to execute arbitrary commands via a long utoken parameter."),
	(1923, "CVE-2000-0427", "2000-05-04T04:00:00.000", "2025-04-03T01:03:51.193", "The Aladdin Knowledge Systems eToken device allows attackers with physical access to the device to obtain sensitive information without knowing the PIN of the owner by resetting the PIN in the EEPROM."),
	(1924, "CVE-2000-0428", "2000-05-04T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the SMTP gateway for InterScan Virus Wall 3.32 and earlier allows a remote attacker to execute arbitrary commands via a long filename for a uuencoded attachment."),
	(1925, "CVE-2000-0381", "2000-05-05T04:00:00.000", "2025-04-03T01:03:51.193", "The Gossamer Threads DBMan db.cgi CGI script allows remote attackers to view environmental variables and setup information by referencing a non-existing database in the db parameter."),
	(1926, "CVE-2000-0423", "2000-05-05T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Netwin DNEWSWEB CGI program allows remote attackers to execute arbitrary commands via long parameters such as group, cmd, and utag."),
	(1927, "CVE-2000-0426", "2000-05-05T04:00:00.000", "2025-04-03T01:03:51.193", "UltraBoard 1.6 and other versions allow remote attackers to cause a denial of service by referencing UltraBoard in the Session parameter, which causes UltraBoard to fork copies of itself."),
	(1928, "CVE-2000-0413", "2000-05-06T04:00:00.000", "2025-04-03T01:03:51.193", "The shtml.exe program in the FrontPage extensions package of IIS 4.0 and 5.0 allows remote attackers to determine the physical path of HTML, HTM, ASP, and SHTML files by requesting a file that does not exist, which generates an error message that reveals the path."),
	(1929, "CVE-2000-0382", "2000-05-08T04:00:00.000", "2025-04-03T01:03:51.193", "ColdFusion ClusterCATS appends stale query string arguments to a URL during HTML redirection, which may provide sensitive information to the redirected site."),
	(1930, "CVE-2000-0383", "2000-05-08T04:00:00.000", "2025-04-03T01:03:51.193", "The file transfer component of AOL Instant Messenger (AIM) reveals the physical path of the transferred file to the remote recipient."),
	(1931, "CVE-2000-0384", "2000-05-08T04:00:00.000", "2025-04-03T01:03:51.193", "NetStructure 7110 and 7180 have undocumented accounts (servnow, root, and wizard) whose passwords are easily guessable from the NetStructure\'s MAC address, which could allow remote attackers to gain root access."),
	(1932, "CVE-2000-0387", "2000-05-09T04:00:00.000", "2025-04-03T01:03:51.193", "The makelev program in the golddig game from the FreeBSD ports collection allows local users to overwrite arbitrary files."),
	(1933, "CVE-2000-0304", "2000-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "Microsoft IIS 4.0 and 5.0 with the IISADMPWD virtual directory installed allows a remote attacker to cause a denial of service via a malformed request to the inetinfo.exe program, aka the \"Undelimited .HTR Request\" vulnerability."),
	(1934, "CVE-2000-0406", "2000-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "Netscape Communicator before version 4.73 and Navigator 4.07 do not properly validate SSL certificates, which allows remote attackers to steal information by redirecting traffic from a legitimate web server to their own malicious server, aka the \"Acros-Suencksen SSL\" vulnerability."),
	(1935, "CVE-2000-0409", "2000-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "Netscape 4.73 and earlier follows symlinks when it imports a new certificate, which allows local users to overwrite files of the user importing the certificate."),
	(1936, "CVE-2000-0410", "2000-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "ColdFusion Server 4.5.1 allows remote attackers to cause a denial of service by making repeated requests to a CFCACHE tagged cache file that is not stored in memory."),
	(1937, "CVE-2000-0411", "2000-05-10T04:00:00.000", "2025-04-03T01:03:51.193", "Matt Wright\'s FormMail CGI script allows remote attackers to obtain environmental variables via the env_report parameter."),
	(1938, "CVE-2000-0408", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "IIS 4.05 and 5.0 allow remote attackers to cause a denial of service via a long, complex URL that appears to contain a large number of file extensions, aka the \"Malformed Extension Data in URL\" vulnerability."),
	(1939, "CVE-2000-0416", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "NTMail 5.x allows network users to bypass the NTMail proxy restrictions by redirecting their requests to NTMail\'s web configuration server."),
	(1940, "CVE-2000-0419", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "The Office 2000 UA ActiveX Control is marked as \"safe for scripting,\" which allows remote attackers to conduct unauthorized activities via the \"Show Me\" function in Office Help, aka the \"Office 2000 UA Control\" vulnerability."),
	(1941, "CVE-2000-0420", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "The default configuration of SYSKEY in Windows 2000 stores the startup key in the registry, which could allow an attacker tor ecover it and use it to decrypt Encrypted File System (EFS) data."),
	(1942, "CVE-2000-0421", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "The process_bug.cgi script in Bugzilla allows remote attackers to execute arbitrary commands via shell metacharacters."),
	(1943, "CVE-2000-0439", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.0 and 5.0 allows a malicious web site to obtain client cookies from another domain by including that domain name and escaped characters in a URL, aka the \"Unauthorized Cookie Access\" vulnerability."),
	(1944, "CVE-2000-0457", "2000-05-11T04:00:00.000", "2025-04-03T01:03:51.193", "ISM.DLL in IIS 4.0 and 5.0 allows remote attackers to read file contents by requesting the file and appending a large number of encoded spaces (%20) and terminated with a .htr extension, aka the \".HTR File Fragment Reading\" or \"File Fragment Reading via .HTR\" vulnerability."),
	(1945, "CVE-2000-0407", "2000-05-12T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Solaris netpr program allows local users to execute arbitrary commands via a long -p option."),
	(1946, "CVE-2000-0415", "2000-05-12T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Outlook Express 4.x allows attackers to cause a denial of service via a mail or news message that has a .jpg or .bmp attachment with a long file name."),
	(1947, "CVE-2000-0400", "2000-05-13T04:00:00.000", "2025-04-03T01:03:51.193", "The Microsoft Active Movie ActiveX Control in Internet Explorer 5 does not restrict which file types can be downloaded, which allows an attacker to download any type of file to a user\'s system by encoding it within an email message or news post."),
	(1948, "CVE-2000-0434", "2000-05-13T04:00:00.000", "2025-04-03T01:03:51.193", "The administrative password for the Allmanage web site administration software is stored in plaintext in a file which could be accessed by remote attackers."),
	(1949, "CVE-2000-0435", "2000-05-13T04:00:00.000", "2025-04-03T01:03:51.193", "The allmanageup.pl file upload CGI script in the Allmanage Website administration software 2.6 can be called directly by remote attackers, which allows them to modify user accounts or web pages."),
	(1950, "CVE-2000-0397", "2000-05-15T04:00:00.000", "2025-04-03T01:03:51.193", "The EMURL web-based email account software encodes predictable identifiers in user session URLs, which allows a remote attacker to access a user\'s email account."),
	(1951, "CVE-2000-0424", "2000-05-15T04:00:00.000", "2025-04-03T01:03:51.193", "The CGI counter 4.0.7 by George Burgyan allows remote attackers to execute arbitrary commands via shell metacharacters."),
	(1952, "CVE-1999-0980", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Windows NT Service Control Manager (SCM) allows remote attackers to cause a denial of service via a malformed argument in a resource enumeration request."),
	(1953, "CVE-2000-0379", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "The Netopia R9100 router does not prevent authenticated users from modifying SNMP tables, even if the administrator has configured it to do so."),
	(1954, "CVE-2000-0389", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in krb_rd_req function in Kerberos 4 and 5 allows remote attackers to gain root privileges."),
	(1955, "CVE-2000-0390", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in krb425_conv_principal function in Kerberos 5 allows remote attackers to gain root privileges."),
	(1956, "CVE-2000-0391", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in krshd in Kerberos 5 allows remote attackers to gain root privileges."),
	(1957, "CVE-2000-0392", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in ksu in Kerberos 5 allows local users to gain root privileges."),
	(1958, "CVE-2000-0393", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "The KDE kscd program does not drop privileges when executing a program specified in a user\'s SHELL environmental variable, which allows the user to gain privileges by specifying an alternate program to execute."),
	(1959, "CVE-2000-0395", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in CProxy 3.3 allows remote users to cause a denial of service via a long HTTP request."),
	(1960, "CVE-2000-0405", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in L0pht AntiSniff allows remote attackers to execute arbitrary commands via a malformed DNS response packet."),
	(1961, "CVE-2000-0432", "2000-05-16T04:00:00.000", "2025-04-03T01:03:51.193", "The calender.pl and the calendar_admin.pl calendar scripts by Matt Kruse allow remote attackers to execute arbitrary commands via shell metacharacters."),
	(1962, "CVE-1999-1008", "2000-05-17T04:00:00.000", "2025-04-03T01:03:51.193", "xsoldier program allows local users to gain root access via a long argument."),
	(1963, "CVE-2000-0350", "2000-05-17T04:00:00.000", "2025-04-03T01:03:51.193", "A debugging feature in NetworkICE ICEcap 2.0.23 and earlier is enabled, which allows a remote attacker to bypass the weak authentication and post unencrypted events."),
	(1964, "CVE-2000-0417", "2000-05-17T04:00:00.000", "2025-04-03T01:03:51.193", "The HTTP administration interface to the Cayman 3220-H DSL router allows remote attackers to cause a denial of service via a long username or password."),
	(1965, "CVE-2000-0464", "2000-05-17T04:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.x and 5.x allows remote attackers to execute arbitrary commands via a buffer overflow in the ActiveX parameter parsing capability, aka the \"Malformed Component Attribute\" vulnerability."),
	(1966, "CVE-2000-0465", "2000-05-17T04:00:00.000", "2025-04-03T01:03:51.193", "Internet Explorer 4.x and 5.x does not properly verify the domain of a  frame within a browser window, which allows a remote attacker to read client files via the frame, aka the \"Frame Domain Verification\" vulnerability."),
	(1967, "CVE-2000-0394", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "NetProwler 3.0 allows remote attackers to cause a denial of service by sending malformed IP packets that trigger NetProwler\'s Man-in-the-Middle signature."),
	(1968, "CVE-2000-0437", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the CyberPatrol daemon \"cyberdaemon\" used in gauntlet and WebShield allows remote attackers to cause a denial of service or execute arbitrary commands."),
	(1969, "CVE-2000-0450", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in bbd server in Big Brother System and Network Monitor allows an attacker to execute arbitrary commands."),
	(1970, "CVE-2000-0452", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the ESMTP service of Lotus Domino Server 5.0.1 allows remote attackers to cause a denial of service via a long MAIL FROM command."),
	(1971, "CVE-2000-0453", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "XFree86 3.3.x and 4.0 allows a user to cause a denial of service via a negative counter value in a malformed TCP packet that is sent to port 6000."),
	(1972, "CVE-2000-0463", "2000-05-18T04:00:00.000", "2025-04-03T01:03:51.193", "BeOS 5.0 allows remote attackers to cause a denial of service via fragmented TCP packets."),
	(1973, "CVE-2000-0305", "2000-05-19T04:00:00.000", "2025-04-03T01:03:51.193", "Windows 95, Windows 98, Windows 2000, Windows NT 4.0, and Terminal Server systems allow a remote attacker to cause a denial of service by sending a large number of identical fragmented IP packets, aka jolt2 or the \"IP Fragment Reassembly\" vulnerability."),
	(1974, "CVE-2000-0436", "2000-05-19T04:00:00.000", "2025-04-03T01:03:51.193", "MetaProducts Offline Explorer 1.2 and earlier allows remote attackers to access arbitrary files via a .. (dot dot) attack."),
	(1975, "CVE-2000-0451", "2000-05-19T04:00:00.000", "2025-04-03T01:03:51.193", "The Intel express 8100 ISDN router allows remote attackers to cause a denial of service via oversized or fragmented ICMP packets."),
	(1976, "CVE-2000-0431", "2000-05-22T04:00:00.000", "2025-04-03T01:03:51.193", "Cobalt RaQ2 and RaQ3 does not properly set the access permissions and ownership for files that are uploaded via FrontPage, which allows attackers to bypass cgiwrap and modify files."),
	(1977, "CVE-2000-0438", "2000-05-22T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in fdmount on Linux systems allows local users in the \"floppy\" group to execute arbitrary commands via a long mountpoint parameter."),
	(1978, "CVE-2000-0418", "2000-05-23T04:00:00.000", "2025-04-03T01:03:51.193", "The Cayman 3220-H DSL router allows remote attackers to cause a denial of service via oversized ICMP echo (ping) requests."),
	(1979, "CVE-2000-0551", "2000-05-23T04:00:00.000", "2025-04-03T01:03:51.193", "The file transfer mechanism in Danware NetOp 6.0 does not provide authentication, which allows remote attackers to access and modify arbitrary files."),
	(1980, "CVE-2000-0396", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "The add.exe program in the Carello shopping cart software allows remote attackers to duplicate files on the server, which could allow the attacker to read source code for web scripts such as .ASP files."),
	(1981, "CVE-2000-0398", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in wconsole.dll in Rockliffe MailSite Management Agent allows remote attackers to execute arbitrary commands via a long query_string parameter in the HTTP GET request."),
	(1982, "CVE-2000-0399", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in MDaemon POP server allows remote attackers to cause a denial of service via a long user name."),
	(1983, "CVE-2000-0441", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Vulnerability in AIX 3.2.x and 4.x allows local users to gain write access to files on locally or remotely mounted AIX filesystems."),
	(1984, "CVE-2000-0442", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Qpopper 2.53 and earlier allows local users to gain privileges via a formatting string in the From: header, which is processed by the euidl command."),
	(1985, "CVE-2000-0443", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "The web interface server in HP Web JetAdmin 5.6 allows remote attackers to read arbitrary files via a .. (dot dot) attack."),
	(1986, "CVE-2000-0444", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "HP Web JetAdmin 6.0 allows remote attackers to cause a denial of service via a malformed URL to port 8000."),
	(1987, "CVE-2000-0445", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "The pgpk command in PGP 5.x on Unix systems uses an insufficiently random data source for non-interactive key pair generation, which may produce predictable keys."),
	(1988, "CVE-2000-0446", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in MDBMS database server allows remote attackers to execute arbitrary commands via a long string."),
	(1989, "CVE-2000-0491", "2000-05-24T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in the XDMCP parsing code of GNOME gdm, KDE kdm, and wdm allows remote attackers to execute arbitrary commands or cause a denial of service via a long FORWARD_QUERY request."),
	(1990, "CVE-2000-0403", "2000-05-25T04:00:00.000", "2025-04-03T01:03:51.193", "The CIFS Computer Browser service on Windows NT 4.0 allows a remote attacker to cause a denial of service by sending a large number of host announcement requests to the master browse tables, aka the \"HostAnnouncement Flooding\" or \"HostAnnouncement Frame\" vulnerability."),
	(1991, "CVE-2000-0404", "2000-05-25T04:00:00.000", "2025-04-03T01:03:51.193", "The CIFS Computer Browser service allows remote attackers to cause a denial of service by sending a ResetBrowser frame to the Master Browser, aka the \"ResetBrowser Frame\" vulnerability."),
	(1992, "CVE-2000-0517", "2000-05-26T04:00:00.000", "2025-04-03T01:03:51.193", "Netscape 4.73 and earlier does not properly warn users about a potentially invalid certificate if the user has previously accepted the certificate for a different web site, which could allow remote attackers to spoof a legitimate web site by compromising that site\'s DNS information."),
	(1993, "CVE-2000-0553", "2000-05-26T04:00:00.000", "2025-04-03T01:03:51.193", "Race condition in IPFilter firewall 3.4.3 and earlier, when configured with overlapping \"return-rst\" and \"keep state\" rules, allows remote attackers to bypass access restrictions."),
	(1994, "CVE-2000-0460", "2000-05-27T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in KDE kdesud on Linux allows local uses to gain privileges via a long DISPLAY environmental variable."),
	(1995, "CVE-2000-0456", "2000-05-28T04:00:00.000", "2025-04-03T01:03:51.193", "NetBSD 1.4.2 and earlier allows local users to cause a denial of service by repeatedly running certain system calls in the kernel which do not yield the CPU, aka \"cpu-hog\"."),
	(1996, "CVE-2000-0462", "2000-05-28T04:00:00.000", "2025-04-03T01:03:51.193", "ftpd in NetBSD 1.4.2 does not properly parse entries in /etc/ftpchroot and does not chroot the specified users, which allows those users to access other files outside of their home directory."),
	(1997, "CVE-2000-0454", "2000-05-29T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in Linux cdrecord allows local users to gain privileges via the dev parameter."),
	(1998, "CVE-2000-0455", "2000-05-29T04:00:00.000", "2025-04-03T01:03:51.193", "Buffer overflow in xlockmore xlock program version 4.16 and earlier allows local users to read sensitive data from memory via a long -mode option."),
	(1999, "CVE-2000-0461", "2000-05-29T04:00:00.000", "2025-04-03T01:03:51.193", "The undocumented semconfig system call in BSD freezes the state of semaphores, which allows local users to cause a denial of service of the semaphore system by using the semconfig call."),
	(2000, "CVE-2000-0564", "2000-05-29T04:00:00.000", "2025-04-03T01:03:51.193", "The guestbook CGI program in ICQ Web Front service for ICQ 2000a, 99b, and others allows remote attackers to cause a denial of service via a URL with a long name parameter.");
